    let v = null; try { v = cfg.streak(); } catch { }
    const sh = shared(); if (sh !== null && v != null) v = { text: sh, label: sh ? `${sh}-day Daily Crown streak` : 'Start your Daily Crown streak' };
    if (v == null) { el.hidden = true; return; }
    el.hidden = false;
