const NAV=[['dashboard','home','My Day'],['library','book','Learn'],['practice','practice','Practice'],['tools','tools','Toolkit'],['progress','growth','My Growth']];
const TOOLS=[['sbar','SBAR conversation guide','Quick tools','Build a clear fictional handover.','sbar'],['teach','Teach-back','Quick tools','Explain, listen, repair and check again.','teachback-skill'],['safety','Before you act','Quick tools','Pause with a practical reflection checklist.','safety'],['evidence','Critical appraisal','Quick tools','Check a fictional claim and plan verification.','ai'],['cus','CUS speaking-up planner','Templates','Make a concern and a requested response clear.','speakup'],['desc','Constructive conflict','Templates','Describe, express, suggest and agree.','conflict'],['huddle','Brief, huddle, debrief','Templates','Name ownership and respond to change.','debrief'],['fishbone','Cause-and-effect map','Templates','Explore possible contributors, then investigate.','human-factors'],['qi','Improvement test','Templates','Plan an approved, measurable small test.','improvement'],['reflect','Reflection space','Wellbeing','Keep one insight and a useful next step.','humility'],['pause','One-minute reset','Wellbeing','An optional quiet pause, at your own pace.','wellbeing'],['movement','Movement demonstrations','Wellbeing','Explore three optional seated movements.','movement']];
const PATHWAYS=[{id:'communication',title:'Clearer communication',description:'Make the next conversation useful.',lessons:['communication','sbar','teachback-skill','documentation','feedback'],activities:['sbar-studio','cc-teach','sim-handover']},{id:'safety',title:'Patient safety',description:'Notice a gap. Make the next action explicit.',lessons:['safety','infection','human-factors','med-transitions','deterioration','just-culture'],activities:['room','cc-reconcile','sim-interruptions']},{id:'person',title:'Person-centred care',description:'Bring the person’s priorities into the plan.',lessons:['empathy','shared','health-literacy','equity','risk-dialogue','dignity'],activities:['cc-access','sim-shared-choice']},{id:'digital',title:'Thoughtful digital practice',description:'Verify claims and handle information carefully.',lessons:['ai','reasoning','risk-evidence','data-stewardship','humility'],activities:['ai-case','cc-verify']},{id:'team',title:'Teams & improvement',description:'Connect a useful conversation to a better process.',lessons:['speakup','conflict','debrief','accountability','inclusive-leadership','improvement','compassion-boundaries','wellbeing'],activities:['cus','huddle','flow','cc-compassion']}];
