/* Incident replay. */
const PX_INCIDENT={
 title:'A delayed escalation (fictional)',
 intro:'Mr Okoye, 68, was admitted for an operation. Over one morning a series of small gaps lined up. Step through the timeline and look for where it could have been caught. Nobody in this story is a villain.',
 events:[
  {id:'e1',time:'06:45',t:'The early observations are recorded and are within Mr Okoye’s usual range.',layer:null,note:'No gap here. This is the baseline.'},
  {id:'e2',time:'08:30',t:'The 08:30 observations fall due as the nurse is called to another bay for an urgent task. The check is deferred and nothing flags it as outstanding.',layer:'Interruptions',note:'The system has no way to show that a check is overdue, or to hand it to a colleague.'},
  {id:'e3',time:'09:10',t:'A healthcare assistant thinks Mr Okoye is “a bit quiet” and mentions it to a colleague passing in the corridor, not to the nurse.',layer:'Speaking up',note:'There is no easy, expected route for a quick “this looks different” message.'},
  {id:'e4',time:'10:00',t:'At handover the outgoing nurse says he is “stable”. The overdue 08:30 check is not mentioned.',layer:'Handover',note:'The handover has no prompt for outstanding checks.'},
  {id:'e5',time:'10:40',t:'The 10:30 observations are recorded but not added up. One value is higher than before. It is not escalated because “we usually repeat it first”.',layer:'Escalation prompts',note:'A habit of repeating before escalating has become normal, and nothing prompts a review.'},
  {id:'e6',time:'11:20',t:'Mr Okoye becomes acutely unwell. The emergency team is called and responds quickly.',layer:null,note:'The outcome. The response was good. The gaps were earlier.'},
  {id:'e7',time:'11:45',t:'The team begins a debrief and agrees to ask what made these gaps possible, not who to blame.',layer:null,note:'A fair review looks at the system as well as the people.'}],
 flagCorrect:['e2','e3','e4','e5'],
 behaviours:[
  {id:'b1',event:'e2',t:'The nurse deferred the 08:30 check to deal with an urgent task in another bay.',best:'error',why:'A reasonable trade-off in the moment, with no way of flagging the deferred check. Console and fix the system, for example a visible “overdue” marker.'},
  {id:'b2',event:'e3',t:'The healthcare assistant mentioned the change informally, rather than telling the nurse.',best:'risk',why:'A drift into an informal habit, with no route making the right way easy. Coach, and make the right route easy and expected.'},
  {id:'b3',event:'e5',t:'A colleague did not escalate a raised value because the usual habit was to repeat it first.',best:'risk',why:'A normalised shortcut. Coach, and add a prompt so the habit is not the default.'},
  {id:'b4',event:null,t:'Contrast example, not part of this incident: a staff member records a set of observations they never took.',best:'reckless',why:'A knowing disregard of an obvious risk and of the records’ purpose. Your organisation’s formal process applies. This is very different from the three behaviours above.'}],
 responses:{error:['Human error','Console and look at the system'],risk:['At-risk behaviour','Coach and make the right way easy'],reckless:['Reckless behaviour','Formal process']},
 layers:['Observations','Interruptions','Speaking up','Handover','Escalation prompts']
};

/* Carecraft Practice Lab. All new Practice views, engines and overrides live here (and in practice-x-data.js / practice-x.css).
   Functions declared earlier in the bundle are reassigned below, the same way the web edition gates openLesson.
   Everything is fictional teaching material: not clinical instruction, not a competency assessment, not CPD. */

/* ---------- 1. Store, helpers, registration ---------- */
const PX_ACTIONS={};
let pxs=null;            /* the active Practice Lab session (scenario, builder, ladder, ...) */
let pxTimer=null;
const pxLevel=id=>PX_LEVELS.find(l=>l.id===id)||PX_LEVELS[1];
const pxSkill=id=>PX_SKILLS.find(s=>s.id===id)||PX_SKILLS[0];
const pxActivity=id=>HCA_ACTIVITIES.find(a=>a.id===id);
const pxNow=()=>new Date().toISOString();
const pxClamp=(n,lo,hi)=>Math.max(lo,Math.min(hi,n));
const pxPct=(a,b)=>b?Math.round(100*a/b):0;
function pxStore(){let p=state.px;if(!p||typeof p!=='object'||Array.isArray(p))p=state.px={};if(!Array.isArray(p.attempts))p.attempts=[];if(!p.cards||typeof p.cards!=='object'||Array.isArray(p.cards))p.cards={};if(!p.prefs||typeof p.prefs!=='object'||Array.isArray(p.prefs))p.prefs={};if(!Number.isFinite(p.drilled))p.drilled=0;return p;}
function pxKind(id){if(PX_SCENARIOS[id])return 'scenario';return ({'px-sbar':'sbar','px-ladder':'ladder','px-priorities':'priority','px-hazard':'hazard','px-incident':'incident'})[id]||null;}
function pxActive(){return !!(pxs&&ui.activity===pxs.id);}
function pxStopTimer(){clearInterval(pxTimer);pxTimer=null;}
function pxShuffle(n){return hcaShuffle(n);}
function pxMins(secs){const m=Math.floor(secs/60),s=secs%60;return m+':'+String(s).padStart(2,'0');}
function pxList(items,tag='ul',cls=''){return `<${tag}${cls?` class="${cls}"`:''}>${items.map(t=>`<li>${esc(t)}</li>`).join('')}</${tag}>`;}

/* New activities join the shared list so search, pathways, My Growth and the checkpoint code all see them. */
for(const a of PX_NEW_ACTIVITIES)if(!HCA_ACTIVITIES.some(x=>x.id===a.id))HCA_ACTIVITIES.push({...a,meta:PX_META[a.id].units+' · About '+PX_META[a.id].min+' min',image:'activity-'+a.id,action:'',icon:a.icon});
const pxOrigMinutes=activityMinutes;
activityMinutes=function(a){const m=PX_META[a.id];return m?m.min:pxOrigMinutes(a);};
const pxOrigGuideFor=ccGuideFor;
ccGuideFor=function(key){const m=PX_META[key];if(!m||!PX_NEW_ACTIVITIES.some(a=>a.id===key))return pxOrigGuideFor(key);const base=pxOrigGuideFor(m.lesson),a=pxActivity(key);return {...base,title:a.title,what:a.desc,how:'Practise: '+m.practise.join('; ')+'.'};};

/* Small glyphs */
function pxLevelBars(level){const n=pxLevel(level).n;return `<svg class="px-bars" viewBox="0 0 18 14" width="18" height="14" aria-hidden="true" focusable="false">${[0,1,2].map(i=>`<rect class="${i<n?'on':''}" x="${i*6.5}" y="${10-i*4}" width="4.5" height="${4+i*4}" rx="1"/>`).join('')}</svg>`;}
function pxLevelBadge(level){const l=pxLevel(level);return `<span class="px-level px-level-${l.id}">${pxLevelBars(l.id)}${l.name}</span>`;}
function pxSkillChip(id){const s=pxSkill(id);return `<span class="px-skill px-skill-${s.id}">${icon(s.icon)}${esc(s.short)}</span>`;}
const PX_Q={best:['Strong choice','✓'],ok:['Acceptable, but incomplete','~'],risk:['Leaves a risk','!']};
function pxQGlyph(q,size=26){const g=({best:'M7 13.5l3.5 3.5L18 9',ok:'M7 12h10',risk:'M12 7v6M12 16.6v.4'})[q]||'';return `<svg class="px-glyph q-${q}" viewBox="0 0 24 24" width="${size}" height="${size}" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="11"/><path d="${g}" fill="none" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
function pxQTag(q){return `<span class="px-tag q-${q}">${pxQGlyph(q,16)}${PX_Q[q][0]}</span>`;}

/* ---------- attempts, coverage, recommendations ---------- */
function pxRecord(rec){const p=pxStore();p.attempts.push(rec);p.attempts=p.attempts.slice(-150);persist();}
function pxAttemptsOf(id){return pxStore().attempts.filter(a=>a.id===id);}
function pxDone(id){return state.studioAttempts.some(r=>activityRecordMatches(r.activity,id))||state.branchRecords.some(r=>r.case===id)||pxAttemptsOf(id).length>0;}
function pxLastDate(id){const d=[...state.studioAttempts.filter(r=>activityRecordMatches(r.activity,id)).map(r=>r.date),...pxAttemptsOf(id).map(a=>a.date),...state.branchRecords.filter(r=>r.case===id).map(r=>r.date)].filter(Boolean).sort();return d.at(-1)||'';}
function pxBestOf(id){const a=pxAttemptsOf(id).filter(r=>r.total);if(!a.length)return null;return a.reduce((m,r)=>r.strong/r.total>m.strong/m.total?r:m);}
function pxCoverage(){return PX_SKILLS.map(s=>{const acts=HCA_ACTIVITIES.filter(a=>PX_META[a.id]?.skill===s.id),done=acts.filter(a=>pxDone(a.id)),reached=done.reduce((n,a)=>Math.max(n,pxLevel(PX_META[a.id].level).n),0);return {skill:s,total:acts.length,done:done.length,value:acts.length?done.length/acts.length:0,reached};});}
function pxDays(n=7){const days=[];for(let i=n-1;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);days.push(localDay(d));}return days;}
function pxActivityDays(){return [...state.studioAttempts,...state.branchRecords,...pxStore().attempts].map(r=>(r.date||'').slice(0,10)).filter(Boolean);}
function pxStreak(){const set=new Set(pxActivityDays());let n=0;const d=new Date();if(!set.has(localDay(d)))d.setDate(d.getDate()-1);while(set.has(localDay(d))){n++;d.setDate(d.getDate()-1);}return n;}
function pxCalibration(){const all=pxStore().attempts.filter(a=>a.calib&&a.calib.n);let n=0,match=0,over=0,under=0;for(const a of all){n+=a.calib.n;match+=a.calib.match;over+=a.calib.over;under+=a.calib.under;}return {n,match,over,under};}
function pxDueCards(){const today=localDay();return Object.entries(pxStore().cards).filter(([k,c])=>c&&c.due<=today&&pxCardResolve(k)).map(([k,c])=>({key:k,...c}));}
function pxRecommend(){
 const saved=state.lastSession;
 if(saved?.kind==='activity'&&pxActivity(saved.id)&&!saved.snapshot?.activitySaved)return {kind:'resume',id:saved.id,title:pxActivity(saved.id).title,why:'Pick up where you left off.',cta:'Continue'};
 const due=pxDueCards();
 if(due.length)return {kind:'drill',n:due.length,title:`Revisit ${due.length} decision${due.length>1?'s':''}`,why:'You chose a less strong option last time. Spaced retrieval is how decisions stick.',cta:'Start the drill'};
 const cov=pxCoverage().filter(c=>c.total>c.done).sort((a,b)=>a.value-b.value||PX_SKILLS.indexOf(a.skill)-PX_SKILLS.indexOf(b.skill));
 for(const c of cov){const next=HCA_ACTIVITIES.filter(a=>PX_META[a.id]?.skill===c.skill.id&&!pxDone(a.id)).sort((a,b)=>pxLevel(PX_META[a.id].level).n-pxLevel(PX_META[b.id].level).n)[0];if(next)return {kind:'activity',id:next.id,title:next.title,why:c.done?`Next step in ${c.skill.name.toLowerCase()}.`:`You have not practised ${c.skill.name.toLowerCase()} yet.`,cta:'Start'};}
 const oldest=HCA_ACTIVITIES.filter(a=>PX_META[a.id]).sort((a,b)=>pxLastDate(a.id).localeCompare(pxLastDate(b.id)))[0];
 return {kind:'activity',id:oldest.id,title:oldest.title,why:'You have tried everything. Revisit the one you have not seen for longest and choose a different path.',cta:'Replay'};}
function pxNextAfter(id){const m=PX_META[id];const pool=HCA_ACTIVITIES.filter(a=>a.id!==id&&PX_META[a.id]&&!pxDone(a.id));if(!pool.length)return HCA_ACTIVITIES[(HCA_ACTIVITIES.findIndex(a=>a.id===id)+1)%HCA_ACTIVITIES.length];const same=pool.filter(a=>PX_META[a.id].skill===m?.skill),lvl=pxLevel(m?.level).n;const pick=arr=>arr.sort((a,b)=>Math.abs(pxLevel(PX_META[a.id].level).n-lvl-1)-Math.abs(pxLevel(PX_META[b.id].level).n-lvl-1))[0];return pick(same.length?same:pool);}

/* ---------- 2. Brief header: what you will practise, how long, what level ---------- */
function pxBriefHTML(id,opts={}){const m=PX_META[id],a=pxActivity(id);if(!m||!a)return '';const g=ccGuideFor(id),skills=[m.skill,...(m.also||[])];
 return `<section class="px-brief" aria-label="About this activity"><div class="px-brief-chips">${pxLevelBadge(m.level)}<span class="px-chip">${icon('clock')}About ${m.min} min</span><span class="px-chip">${esc(m.units)}</span><span class="px-chip px-chip-fw">${esc(m.fw)}</span>${skills.map(pxSkillChip).join('')}</div><details class="px-brief-more"${opts.open?' open':''}><summary>What you will practise</summary>${pxList(m.practise)}<p class="px-brief-why"><b>Why it matters.</b> ${esc(g.why||'')}</p><p class="px-brief-how"><b>How it works.</b> ${esc(opts.how||g.how||'')}</p></details></section>`;}
const pxOrigBrief=ccActivityBrief;
ccActivityBrief=function(key){if(!PX_META[key])return pxOrigBrief(key);const g=ccGuideFor(key);return pxBriefHTML(key,{how:g.how,open:!(ui.history&&ui.history.length)})+`<div class="px-brief-links"><button class="text-link" data-action="engine-30" data-engine-30="${esc(JSON.stringify([g.evidence]))}">${hcaIcon('research')} Research context →</button></div>`;};
const pxOrigShowModal=showModal;
showModal=function(title,subtitle,body,tag,tabs){const a=ui.activity?pxActivity(ui.activity):null;if(a&&PX_META[a.id]&&!pxKind(a.id)&&!/px-brief|cc-activity-brief|class="px-/.test(body)&&String(title)===a.title)body=pxBriefHTML(a.id,{open:!(ui.history&&ui.history.length)})+body;return pxOrigShowModal.call(this,title,subtitle,body,tag,tabs);};
const pxOrigRenderActivity=renderActivity;
renderActivity=function(){const html=pxOrigRenderActivity();const a=pxActivity(ui.activity);if(!a||!PX_META[a.id])return html;return html.replace('<section class="studio-workbench"',pxBriefHTML(a.id,{open:true})+'<section class="studio-workbench"');};

/* ---------- 3. Launch routing, checkpoints, step bar ---------- */
const PX_ENGINES={};
const pxOrigStartCase=startCase;
startCase=function(id){if(PX_SCENARIOS[id]){ui.activity=id;ccCurrentGuide=id;pxOpen(id);return;}return pxOrigStartCase(id);};
const pxOrigOpenAdv=openAdv;
openAdv=function(id){if(pxKind(id)){pxOpen(id);return;}return pxOrigOpenAdv(id);};
const pxOrigAdvStop=advStop;
advStop=function(){pxStopTimer();return pxOrigAdvStop.apply(this,arguments);};
function pxOpen(id){const kind=pxKind(id);if(!kind)return;pxs=null;ccCurrentGuide=id;PX_ENGINES[kind].open(id);}
function pxRender(){if(!pxs)return;PX_ENGINES[pxs.kind].render();}
function pxCompact(s){const {hist,...rest}=s;return JSON.parse(JSON.stringify(rest));}
function pxPush(){if(!pxs)return;(pxs.hist||(pxs.hist=[])).push(JSON.stringify(pxCompact(pxs)));if(pxs.hist.length>60)pxs.hist.shift();ui.dirty=true;}
function pxBack(){if(!pxs||!pxs.hist||!pxs.hist.length||pxs.finished)return;const hist=pxs.hist,prev=JSON.parse(hist.pop()),next=PX_ENGINES[pxs.kind].sanitize(prev);if(!next)return;pxs=next;pxs.hist=hist;pxRender();}
function pxSnapshot(){const base={studioTab:'hygiene',hygieneIndex:0,hygieneAnswers:[],hygieneSelected:null,hotspotSelected:-1,sbarSlots:[null,null,null,null],sbarSelected:null,sbarChecked:false,sbarGuided:false,sbarAcknowledged:false,movementId:'chest',movementSafety:false,movementCycles:1,advMode:'',cusStep:0,cusSelected:null,cusHistory:[],huddleStep:0,huddleHistory:[],simStep:0,simServed:0,simQueue:0,simRework:0,simHistory:[],simCapacity:3},px=pxCompact(pxs);if(cases.some(c=>c.id===pxs.id))return {branchSession:{case:pxs.id,stage:0,path:[],firstHelpful:false,selected:null},px};return {...base,px};}
const pxOrigCapture=captureActivity;
captureActivity=function(){if(!ui.activity||!pxActive())return pxOrigCapture();state.lastSession={kind:'activity',id:ui.activity,snapshot:JSON.parse(JSON.stringify({...pxSnapshot(),activitySaved:!!ui.activitySaved})),date:new Date().toISOString()};store.save();};
const pxOrigRestore=restoreCheckpoint;
restoreCheckpoint=function(saved){const x=saved?.snapshot||{};if(x.px&&pxKind(saved.id)){ui.activity=saved.id;ui.activitySaved=!!x.activitySaved;ccCurrentGuide=saved.id;const engine=PX_ENGINES[pxKind(saved.id)];let next=null;try{next=x.px.id===saved.id&&x.px.kind===pxKind(saved.id)?engine.sanitize(x.px):null;}catch{next=null;}if(next){pxs=next;pxs.hist=[];pxRender();}else pxOpen(saved.id);captureActivity();return;}return pxOrigRestore(saved);};
const pxOrigFinished=activityFinished;
activityFinished=function(){if(pxActive())return !!pxs.finished;return pxOrigFinished();};
const pxOrigNextTarget=activityNextTarget;
activityNextTarget=function(host){if(pxActive()){const b=host.querySelector('[data-px-next]:not(:disabled)');return b&&!b.closest('#presentControls,.activity-stepbar')?b:undefined;}return pxOrigNextTarget(host);};
const pxOrigBack=activityBack;
activityBack=function(){if(pxActive()){pxBack();return;}return pxOrigBack();};
const pxOrigSync=syncActivityUI;
syncActivityUI=function(){pxOrigSync();if(pxActive()){const host=$('#modal').open?$('#modal'):$('#main'),back=host.querySelector('[data-action="activity-back"]');if(back)back.disabled=!pxs.hist?.length||!!pxs.finished;}};
const pxOrigFinishExtras=finishExtras;
finishExtras=function(){if(!ui.activity||!activityFinished())return '';const a=pxActivity(ui.activity),m=a&&PX_META[a.id];if(!m)return pxOrigFinishExtras();const nxt=pxNextAfter(a.id),g=ccGuideFor(a.id),due=pxDueCards().length;
 return `<section class="finish-screen px-finish"><span class="eyebrow">WHAT YOU PRACTISED</span><h3>${esc(a.title)}</h3><div class="px-brief-chips">${pxLevelBadge(m.level)}${[m.skill,...(m.also||[])].map(pxSkillChip).join('')}</div>${pxList(m.practise)}<h4>One thing to try</h4><p>${esc(g.why)}</p>${due?`<p class="px-finish-due">${icon('calendar')}${due} decision${due>1?'s are':' is'} waiting in your retrieval drill.</p>`:''}<p class="footnote">Saved attempts describe learning activity, not clinical competence. Everything here is fictional and does not replace local policy or training.</p><div class="px-finish-actions">${btn('Next: '+esc(nxt.title)+' →','activity',[nxt.id],'secondary')}${btn('Practice hub','navigate',['practice'],'ghost')}${btn('View My Growth','navigate',['progress'],'ghost')}</div></section>`;};

/* ---------- 4. Shared debrief components ---------- */
function pxMeterRow(defs,vals,prev){return `<div class="px-meters" role="group" aria-label="Scenario indicators (illustrative)">${defs.map(([k,label])=>{const v=vals[k],p=prev?prev[k]:v,d=v-p;return `<div class="px-meter" role="img" aria-label="${esc(label)}: ${v} of 5${d?(d>0?', up':', down'):''}"><span class="px-meter-l">${esc(label)}${d?`<b class="${d>0?'up':'down'}" aria-hidden="true">${d>0?'▲':'▼'}</b>`:''}</span><span class="px-pips" aria-hidden="true">${[1,2,3,4,5].map(i=>`<i class="${i<=v?'on':''}"></i>`).join('')}</span></div>`;}).join('')}</div>`;}
function pxPathMap(items){const n=items.length,W=Math.max(320,n*120),H=170,x=i=>n===1?W/2:60+i*(W-120)/(n-1);
 let svg=`<svg class="px-pathsvg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Decision path: ${items.map((t,i)=>'decision '+(i+1)+' '+PX_Q[t.q][0]).join(', ')}">`;
 svg+=`<path class="px-route" d="M${x(0)} 110H${x(n-1)}"/>`;
 items.forEach((t,i)=>{if(t.q!=='best'){const cx=x(i),x0=i?x(i-1):cx-50,x1=i<n-1?x(i+1):cx+50;svg+=`<path class="px-alt" d="M${x0} 110C${x0+30} 110 ${cx-40} 46 ${cx} 46S${x1-30} 110 ${x1} 110" fill="none"/><g class="px-star" transform="translate(${cx} 46)"><circle r="12"/><path d="M0-6l1.8 3.8 4.2.6-3 3 .7 4.2L0 3.6-3.7 5.6l.7-4.2-3-3 4.2-.6z" transform="scale(.95)"/></g>`;}});
 items.forEach((t,i)=>{const cx=x(i);svg+=`<g transform="translate(${cx} 110)" class="px-n q-${t.q}"><circle r="17"/><path d="${({best:'M-7 1l5 5 9-10',ok:'M-7 0h14',risk:'M0-8v9M0 6v.8'})[t.q]}" fill="none" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></g><text x="${cx}" y="148" text-anchor="middle" class="px-nlabel">Decision ${i+1}</text>`;});
 svg+='</svg>';
 return `<figure class="px-pathmap"><div class="px-pathscroll">${svg}</div><figcaption class="px-legend"><span>${pxQGlyph('best',16)}Strong</span><span>${pxQGlyph('ok',16)}Acceptable, incomplete</span><span>${pxQGlyph('risk',16)}Leaves a risk</span><span><svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" class="px-star-i"><circle cx="12" cy="12" r="11"/></svg>Stronger route (dashed)</span></figcaption></figure>
 <ol class="px-path">${items.map((t,i)=>`<li class="px-step q-${t.q}"><div class="px-step-head">${pxQGlyph(t.q,28)}<div><strong>Decision ${i+1} · ${esc(t.title)}</strong><div class="px-step-tags">${pxQTag(t.q)}${t.fw?`<span class="px-chip">${esc(t.fw)}</span>`:''}${t.conf?`<span class="px-chip">${esc(['','Not sure','Fairly sure','Very sure'][t.conf])}</span>`:''}${t.over?'<span class="px-chip">Over time</span>':''}${t.hint?'<span class="px-chip">Hint used</span>':''}</div></div></div><div class="px-compare"><div class="px-you"><small>You chose</small><p>${esc(t.you)}</p></div><div class="px-better"><small>${t.q==='best'?'The stronger approach (yours)':'Stronger approach'}</small><p>${esc(t.q==='best'?'You chose it. '+t.betterWhy:t.better)}</p></div></div><p class="px-cons"><b>What happened.</b> ${esc(t.cons)}</p><details><summary>Why</summary><p>${esc(t.why)}</p>${t.q!=='best'?`<p><b>Why the stronger approach works.</b> ${esc(t.betterWhy)}</p>`:''}</details></li>`).join('')}</ol>`;}
function pxFrameworkStrip(fw,items){return `<div class="px-fwstrip" role="list" aria-label="${esc(fw.name)}: how your choices mapped to each step">${fw.steps.map(([k,name])=>{const hit=items.filter(t=>t.fwKey===k);const q=!hit.length?'none':hit.some(t=>t.q==='risk')?'risk':hit.every(t=>t.q==='best')?'best':'ok';return `<div class="px-fwstep q-${q}" role="listitem"><b>${esc(k)}</b><span>${esc(name)}</span><em>${q==='none'?'Not exercised':PX_Q[q][0]}</em></div>`;}).join('')}</div>`;}
function pxCalibMatrix(rows){if(!rows.length)return '';const cells={};for(const r of rows){const k=r.conf+(r.q==='best'?'y':'n');cells[k]=(cells[k]||0)+1;}const lab=['','Not sure','Fairly sure','Very sure'];
 return `<table class="px-calib"><caption>Confidence against outcome (your decisions this run)</caption><thead><tr><th scope="col">How sure you were</th><th scope="col">Strongest choice</th><th scope="col">Not the strongest</th></tr></thead><tbody>${[3,2,1].map(c=>`<tr><th scope="row">${lab[c]}</th><td>${'●'.repeat(cells[c+'y']||0)||'<span class="px-nil">none</span>'}</td><td>${'○'.repeat(cells[c+'n']||0)||'<span class="px-nil">none</span>'}</td></tr>`).join('')}</tbody></table>`;}
function pxCalibStats(rows){let match=0,over=0,under=0;for(const r of rows){const good=r.q==='best';if(r.conf===3&&!good)over++;else if(r.conf===1&&good)under++;else if((r.conf===3&&good)||(r.conf===1&&!good)||r.conf===2)match++;}return {n:rows.length,match,over,under};}
function pxCalibText(c){if(!c.n)return '';const parts=[];if(c.over)parts.push(`You were very sure on ${c.over} decision${c.over>1?'s':''} that were not the strongest. Those are the ones worth a second look: confidence and correctness are not the same.`);if(c.under)parts.push(`You were unsure on ${c.under} decision${c.under>1?'s':''} where you chose the strongest option. Your instinct was better than you gave it credit for. Notice what you were drawing on.`);if(!c.over&&!c.under)parts.push('Your confidence lined up with the outcomes this time. Keep checking it: ease of recall can feel like certainty.');parts.push('This is your own pattern for this one activity, not a score.');return parts.join(' ');}

/* ---------- 5. Branching scenario engine ---------- */
const PX_TIMER_SECONDS=45;
function pxExhibit(ex){if(!ex)return '';const cap=ex.title?`<figcaption>${esc(ex.title)}</figcaption>`:'';
 if(ex.type==='table')return `<figure class="px-exhibit">${cap}<div class="px-tablewrap"><table><thead><tr>${ex.head.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${ex.rows.map(r=>`<tr>${r.map((c,i)=>i?`<td>${esc(c)}</td>`:`<th scope="row">${esc(c)}</th>`).join('')}</tr>`).join('')}</tbody></table></div>${ex.note?`<p class="px-exnote">${esc(ex.note)}</p>`:''}</figure>`;
 if(ex.type==='say')return `<figure class="px-exhibit px-say">${cap}${ex.lines.map(([who,line])=>`<p class="px-line${/^you$/i.test(who)?' me':''}"><b>${esc(who)}</b><span>${esc(line)}</span></p>`).join('')}</figure>`;
 if(ex.type==='note')return `<figure class="px-exhibit px-note">${cap}${pxList(ex.lines)}</figure>`;
 return '';}
function pxOrder(node,n){pxs.order=pxs.order||{};if(!Array.isArray(pxs.order[node])||pxs.order[node].length!==n)pxs.order[node]=pxShuffle(n);return pxs.order[node];}
function pxMeters(){return pxs.meters;}
function pxStartScenario(id){const sc=PX_SCENARIOS[id],m=PX_META[id],p=pxStore().prefs;
 pxs={kind:'scenario',id,phase:'setup',guided:typeof p.guided==='boolean'?p.guided:m.level==='foundation',timed:!!p.timed,conf:p.conf!==false,node:sc.start,path:[],sel:null,rate:null,locked:false,hint:false,over:false,order:{},meters:{clarity:3,safety:3,trust:3},prevMeters:{clarity:3,safety:3,trust:3},started:Date.now(),finished:false,hist:[]};
 ui.activitySaved=false;ui.lastSavedAttempt=null;ui.history=[];ui.dirty=false;pxRender();}
function pxScenarioSanitize(x){const sc=PX_SCENARIOS[x.id];if(!sc||!['setup','play','debrief'].includes(x.phase)||!sc.nodes[x.node]||!Array.isArray(x.path))return null;
 const path=[];for(const e of x.path){const n=sc.nodes[e.node];if(!n||!Number.isInteger(e.opt)||!n.opts[e.opt])return null;path.push({node:e.node,opt:e.opt,q:n.opts[e.opt].q,conf:[0,1,2,3].includes(e.conf)?e.conf:0,over:!!e.over,hint:!!e.hint,ms:Number.isFinite(e.ms)?e.ms:0,after:e.after&&typeof e.after==='object'?e.after:null});}
 const n=sc.nodes[x.node],order={};if(x.order&&typeof x.order==='object')for(const [k,v] of Object.entries(x.order))if(sc.nodes[k]&&Array.isArray(v)&&v.length===sc.nodes[k].opts.length&&new Set(v).size===v.length&&v.every(i=>Number.isInteger(i)&&i>=0&&i<v.length))order[k]=v;
 const meters={},prev={};for(const [k] of sc.meters){meters[k]=pxClamp(+x.meters?.[k]||3,1,5);prev[k]=pxClamp(+x.prevMeters?.[k]||3,1,5);}
 const sel=Number.isInteger(x.sel)&&x.sel>=0&&x.sel<n.opts.length?x.sel:null;
 return {kind:'scenario',id:x.id,phase:x.phase,guided:!!x.guided,timed:!!x.timed,conf:x.conf!==false,node:x.node,path,sel,rate:[1,2,3].includes(x.rate)?x.rate:null,locked:!!x.locked&&sel!==null,hint:!!x.hint,over:!!x.over,order,meters,prevMeters:prev,started:Number.isFinite(x.started)?x.started:Date.now(),finished:x.phase==='debrief'&&!!x.finished,saved:!!x.saved,note:typeof x.note==='string'?x.note.slice(0,400):'',nodeStart:Number.isFinite(x.nodeStart)?x.nodeStart:Date.now(),hist:[]};}
function pxScenarioPhaseLabel(){const s=pxs,m=PX_META[s.id];return `Fictional practice · ${pxLevel(m.level).name} · about ${m.min} min`;}
function pxScenarioRender(){const s=pxs,a=pxActivity(s.id);let body;if(s.phase==='setup')body=pxScenarioSetup();else if(s.phase==='debrief')body=pxScenarioDebrief();else body=pxScenarioPlay();
 showModal(esc(a.title),pxScenarioPhaseLabel(),body);const d=document.getElementById('modal');d.classList.add('tool-workspace','px-modal');
 requestAnimationFrame(()=>{const target=s.phase==='play'&&s.locked?d.querySelector('.px-feedback'):s.phase==='play'?d.querySelector('.px-q'):s.phase==='debrief'?d.querySelector('.px-outcome'):d.querySelector('.px-setup h3');if(target){target.tabIndex=-1;target.focus({preventScroll:false});}});
 if(s.phase==='play'&&s.timed&&!s.locked)pxTimerStart();}
function pxScenarioSetup(){const s=pxs,sc=PX_SCENARIOS[s.id],m=PX_META[s.id];
 const group=(key,label,opts,cur)=>`<div class="px-pref" role="radiogroup" aria-label="${esc(label)}"><span class="px-pref-l">${esc(label)}</span><div class="px-seg">${opts.map(([v,t])=>`<button type="button" class="px-segbtn" role="radio" aria-checked="${String(cur)===String(v)}" data-action="px-pref" data-arg0="${key}" data-arg1="${v}">${esc(t)}</button>`).join('')}</div></div>`;
 return `<div class="px-setup">${pxBriefHTML(s.id,{open:true,how:'You make a decision, see what it leads to, then read a debrief that compares your path with a stronger one.'})}<section class="px-card"><h3>The situation</h3><p class="px-meta"><b>Setting.</b> ${esc(sc.setting)}</p><p class="px-meta"><b>Your role.</b> ${esc(sc.role)}</p><p>${esc(sc.intro)}</p><p class="px-fwline"><b>Framework in focus.</b> ${esc(sc.fw.name)}: ${sc.fw.steps.map(([k,t])=>`<span class="px-chip"><b>${esc(k)}</b> ${esc(t)}</span>`).join(' ')}</p></section>
 <section class="px-card"><h3>Choose how to practise</h3>${group('guided','Support',[[true,'Guided: cues and hints'],[false,'Independent']],s.guided)}${group('timed','Timing',[[false,'Untimed'],[true,`Timed: ${PX_TIMER_SECONDS} seconds a decision`]],s.timed)}${group('conf','Confidence ratings',[[true,'On: rate how sure you are'],[false,'Off']],s.conf)}<p class="field-hint">Timing is soft. Time running out never locks you out. In real work, delay is also a decision. Confidence ratings help you notice when feeling sure and being right come apart.</p></section>
 <div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-begin">Start the scenario →</button></div></div>`;}
function pxScenarioPlay(){const s=pxs,sc=PX_SCENARIOS[s.id],node=sc.nodes[s.node],order=pxOrder(s.node,node.opts.length),depth=s.path.length+1,lastPath=s.path.at(-1),prevNode=lastPath&&s.path.length&&!s.locked?sc.nodes[lastPath.node].opts[lastPath.opt]:null;
 const selected=s.sel!==null,chosen=selected?node.opts[order[s.sel]]:null,lockedNow=s.locked;
 const maxDepth=pxScenarioMaxDepth(sc);
 const cue=s.guided?`<details class="px-cue" open><summary>Framework cue: ${esc(sc.fw.name)}</summary><ol class="px-cue-steps">${sc.fw.steps.map(([k,t])=>`<li class="${k===node.fw?'now':''}"><b>${esc(k)}</b> ${esc(t)}${k===node.fw?' <em>(this decision)</em>':''}</li>`).join('')}</ol></details>`:'';
 const opts=order.map((oi,di)=>{const o=node.opts[oi],isSel=s.sel===di,cls=lockedNow?(o.q==='best'?'correct':isSel?'incorrect':''):'';return `<button type="button" class="answer px-opt ${isSel?'is-selected':''} ${cls}" aria-pressed="${isSel}" ${lockedNow?'disabled':''} data-action="px-pick" data-arg0="${di}"><span class="letter">${'ABCD'[di]}</span><span class="px-opt-t">${esc(o.t)}</span>${lockedNow?`<span class="px-opt-q q-${o.q}">${pxQGlyph(o.q,18)}<span class="px-sr">${PX_Q[o.q][0]}</span>${isSel?'<small>Your choice</small>':''}</span>`:''}</button>`;}).join('');
 const rate=(selected&&s.conf&&!lockedNow)?`<div class="px-rate" role="radiogroup" aria-label="How sure are you that this is the strongest response?"><span class="px-pref-l">How sure are you that this is the strongest response?</span><div class="px-seg">${[[1,'Not sure'],[2,'Fairly sure'],[3,'Very sure']].map(([v,t])=>`<button type="button" class="px-segbtn" role="radio" aria-checked="${s.rate===v}" data-action="px-rate" data-arg0="${v}">${t}</button>`).join('')}</div></div>`:'';
 const lockBtn=(selected&&!lockedNow&&s.conf)?`<button type="button" class="btn" data-px-next data-action="px-lock" ${s.rate?'':'disabled'}>Lock in my answer →</button>`:'';
 const hintBtn=(s.guided&&!lockedNow)?`<div class="px-hint">${s.hint?`<p class="px-hint-t" role="note"><b>Hint.</b> ${esc(node.hint)}</p>`:`<button type="button" class="btn secondary" data-action="px-hint">Show a hint</button>`}</div>`:'';
 const timer=(s.timed&&!lockedNow)?`<div class="px-clock" id="pxClockWrap"><span class="px-clock-l">Time</span><span id="pxClock" role="timer" aria-live="off">${pxMins(Math.max(0,PX_TIMER_SECONDS-Math.floor((Date.now()-(s.nodeStart||Date.now()))/1000)))}</span><span id="pxClockMsg" class="px-clock-m"></span></div>`:'';
 let fb='';if(lockedNow){const e=s.path.at(-1),best=node.opts.find(o=>o.q==='best'),c=chosen;const calib=e.conf?(e.conf===3&&c.q!=='best'?'You were very sure here, and this was not the strongest option. Worth noticing.':e.conf===1&&c.q==='best'?'You were unsure, yet chose the strongest option. Your instinct served you.':e.conf===3?'Very sure and strong. Well calibrated.':''):'';
  fb=`<section class="px-feedback q-${c.q}" aria-live="polite"><div class="px-fb-head">${pxQGlyph(c.q,30)}<div><strong>${PX_Q[c.q][0]}</strong>${e.over?'<span class="px-chip">Over time</span>':''}</div></div><p>${esc(c.why)}</p>${calib?`<p class="px-calib-note">${esc(calib)}</p>`:''}<div class="px-then"><b>What happens next.</b> ${esc(c.then)}</div>${pxMeterRow(sc.meters,s.meters,s.prevMeters)}${c.q!=='best'?`<details open><summary>The stronger approach</summary><p>${esc(best.t)}</p><p>${esc(best.why)}</p></details>`:''}<details><summary>Compare all the options</summary>${order.map((oi,di)=>{const o=node.opts[oi];return `<div class="px-cmp q-${o.q}">${pxQTag(o.q)}<p><b>${'ABCD'[di]}.</b> ${esc(o.t)}</p><p class="px-cmp-why">${esc(o.why)}</p></div>`;}).join('')}</details></section><div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-next">${c.to==='end'?'See my debrief':'Continue'} →</button></div>`;}
 return `<div class="px-play"><div class="px-progress" aria-label="Decision ${depth}${maxDepth>depth?' of up to '+maxDepth:''}"><span>Decision ${depth}${maxDepth>1?` of up to ${maxDepth}`:''}</span><span class="px-pips-lg" aria-hidden="true">${Array.from({length:maxDepth},(_,i)=>`<i class="${i<s.path.length?'done':i===s.path.length?'now':''}"></i>`).join('')}</span></div>${pxMeterRow(sc.meters,s.meters,lockedNow?s.prevMeters:null)}${cue}<article class="px-scene">${prevNode?`<div class="px-then px-then-band"><b>What happened next.</b> ${esc(prevNode.then)}</div>`:''}<h3 class="px-scene-t">${esc(node.title)}</h3><p>${esc(node.scene)}</p>${pxExhibit(node.exhibit)}</article><h3 class="px-q">${esc(node.q)}</h3>${timer}<div class="px-opts answer-list" role="group" aria-label="Your options">${opts}</div>${hintBtn}${rate}${lockBtn?`<div class="modal-actions">${lockBtn}</div>`:''}${fb}</div>`;}
function pxScenarioMaxDepth(sc){const walk=(id,d)=>Math.max(...sc.nodes[id].opts.map(o=>o.to==='end'?d:walk(o.to,d+1)));return walk(sc.start,1);}
function pxTimerStart(){pxStopTimer();const s=pxs;if(!s)return;s.nodeStart=s.nodeStart||Date.now();const tick=()=>{if(!pxs||pxs!==s||s.locked)return pxStopTimer();const left=Math.max(0,PX_TIMER_SECONDS-Math.floor((Date.now()-s.nodeStart)/1000)),el=document.getElementById('pxClock');if(el)el.textContent=pxMins(left);const msg=document.getElementById('pxClockMsg');if(left===0&&!s.over){s.over=true;if(msg)msg.textContent='Time is up. In real work, not deciding is also a decision. Choose when you are ready.';document.getElementById('pxClockWrap')?.classList.add('over');}};tick();pxTimer=setInterval(tick,1000);}
function pxScenarioLock(){const s=pxs,sc=PX_SCENARIOS[s.id],node=sc.nodes[s.node],order=pxOrder(s.node,node.opts.length);if(s.sel===null||s.locked)return;const oi=order[s.sel],o=node.opts[oi];pxStopTimer();s.prevMeters={...s.meters};for(const k of Object.keys(s.meters))s.meters[k]=pxClamp(s.meters[k]+(o.fx?.[k]||0),1,5);
 s.path.push({node:s.node,opt:oi,q:o.q,conf:s.conf?s.rate||0:0,over:!!s.over,hint:!!s.hint,ms:Date.now()-(s.nodeStart||Date.now()),after:{...s.meters}});s.locked=true;}
function pxResult(s){const sc=PX_SCENARIOS[s.id],n=s.path.length,strong=s.path.filter(e=>e.q==='best').length,risk=s.path.filter(e=>e.q==='risk').length,ok=n-strong-risk;const ending=risk>=2||(risk>=1&&strong<n/2)?'weak':strong>=n-1&&!risk?'strong':'mixed';return {n,strong,ok,risk,ending,over:s.path.filter(e=>e.over).length,hints:s.path.filter(e=>e.hint).length,rows:s.path.filter(e=>e.conf).map(e=>({conf:e.conf,q:e.q}))};}
function pxScenarioItems(s){const sc=PX_SCENARIOS[s.id];return s.path.map(e=>{const node=sc.nodes[e.node],o=node.opts[e.opt],best=node.opts.find(x=>x.q==='best');return {title:node.title,fw:(sc.fw.steps.find(x=>x[0]===node.fw)||[])[1],fwKey:node.fw,q:e.q,you:o.t,better:best.t,betterWhy:best.why,cons:o.then,why:o.why,conf:e.conf,over:e.over,hint:e.hint};});}
function pxScenarioFinish(){const s=pxs,sc=PX_SCENARIOS[s.id],m=PX_META[s.id],R=pxResult(s),calib=pxCalibStats(R.rows);s.phase='debrief';s.finished=true;s.secs=Math.round((Date.now()-s.started)/1000);
 pxRecord({id:s.id,kind:'scenario',date:pxNow(),level:m.level,mode:{guided:s.guided,timed:s.timed,conf:s.conf},strong:R.strong,ok:R.ok,risk:R.risk,total:R.n,over:R.over,hints:R.hints,calib,secs:s.secs,path:s.path.map(e=>({n:e.node,o:e.opt,q:e.q,c:e.conf}))});
 const prefs=pxStore().prefs;prefs.guided=s.guided;prefs.timed=s.timed;prefs.conf=s.conf;
 let queued=0;for(const e of s.path)if(e.q!=='best'){const key=`s:${s.id}:${e.node}`;const c=pxStore().cards;if(!c[key]){c[key]={box:0,due:laterDay(1)};queued++;}else{c[key].box=0;c[key].due=laterDay(1);queued++;}}
 s.queued=queued;let reviewNote='';if(R.risk&&lessons.some(l=>l.id===m.lesson)){const old=state.reviewQueue[m.lesson];if(!old||old.due>laterDay(1)){state.reviewQueue[m.lesson]={due:laterDay(1),streak:Math.min(old?.streak||0,1)};reviewNote=lessons.find(l=>l.id===m.lesson).title;}}s.reviewNote=reviewNote;
 const detail=`${R.strong} of ${R.n} decisions were the strongest option${R.risk?`; ${R.risk} left a risk`:''}. Level: ${pxLevel(m.level).name}. ${s.guided?'Guided':'Independent'}${s.timed?', timed':''}.\n\n`+s.path.map((e,i)=>{const node=sc.nodes[e.node],o=node.opts[e.opt];return `${i+1}. ${node.title} (${PX_Q[e.q][0]})\nChose: ${o.t}\n${o.why}`;}).join('\n\n')+'\n\nOriginal fictional scenario. A learning record, not a measure of clinical competence.';
 persist();logStudio(s.id,pxActivity(s.id).title,detail);s.saved=true;}
function pxScenarioDebrief(){const s=pxs,sc=PX_SCENARIOS[s.id],m=PX_META[s.id],R=pxResult(s),items=pxScenarioItems(s),calib=pxCalibStats(R.rows),endTitle={strong:'A strong outcome',mixed:'A mixed outcome',weak:'A difficult outcome'}[R.ending];
 const tiles=[[`${R.strong} of ${R.n}`,'strongest choices'],[R.n-R.strong?`${R.n-R.strong}`:'0','to revisit'],[s.timed?(R.over?`${R.over}`:'0'):'—',s.timed?'decisions over time':'untimed'],[R.rows.length?`${calib.match} of ${calib.n}`:'—',R.rows.length?'confidence matched':'no ratings']];
 return `<div class="px-debrief"><section class="px-outcome px-outcome-${R.ending}"><span class="eyebrow">WHAT HAPPENED IN THE STORY</span><h3>${endTitle}</h3><p>${esc(sc.endings[R.ending])}</p></section>
 <section class="px-tiles" aria-label="Your run at a glance">${tiles.map(([v,l])=>`<div class="px-tile"><strong>${esc(v)}</strong><span>${esc(l)}</span></div>`).join('')}</section>
 <section class="px-sec"><h3>Your decision path</h3>${pxPathMap(items)}</section>
 <section class="px-sec"><h3>${esc(sc.fw.name)}: where your choices landed</h3>${pxFrameworkStrip(sc.fw,items)}</section>
 <section class="px-sec"><h3>How the story moved</h3>${pxMeterRow(sc.meters,s.meters,{clarity:3,safety:3,trust:3})}<p class="field-hint">Indicators run from 1 to 5, start at 3 and are set by the scenario author to show how choices carry forward. They are illustrative, not measurements of any real outcome.</p></section>
 ${R.rows.length?`<section class="px-sec"><h3>Confidence and calibration</h3>${pxCalibMatrix(R.rows)}<p>${esc(pxCalibText(calib))}</p></section>`:''}
 <section class="px-sec px-take"><h3>Take-aways</h3>${pxList(sc.takeaways)}</section>
 <section class="px-sec"><h3>Your next step</h3><label for="pxNote">${esc(sc.reflect)} <span class="field-hint">Optional. Stays on this device.</span></label><textarea id="pxNote" rows="3" maxlength="400" data-oninput="px-note">${esc(s.note||'')}</textarea></section>
 <p class="px-saved" role="status">${icon('check')}Saved to My Growth.${s.queued?` ${s.queued} decision${s.queued>1?'s':''} added to your retrieval drill for tomorrow.`:''}${s.reviewNote?` A Smart Review prompt on “${esc(s.reviewNote)}” is due tomorrow.`:''}</p>
 <div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-replay">Replay and choose differently →</button><button type="button" class="btn secondary" data-action="px-explore">Explore the other branches</button><button class="text-link" data-action="engine-36" data-engine-36="${esc(JSON.stringify([m.lesson]))}">Related lesson →</button></div></div>`;}
PX_ENGINES.scenario={open:pxStartScenario,render:pxScenarioRender,sanitize:pxScenarioSanitize};
PX_ACTIONS['px-pref']=([k,v])=>{if(!pxs||pxs.kind!=='scenario'||pxs.phase!=='setup')return;if(['guided','timed','conf'].includes(k)){pxs[k]=v==='true'||v===true;pxRender();}};
PX_ACTIONS['px-begin']=()=>{if(!pxs||pxs.phase!=='setup')return;pxPush();pxs.phase='play';pxs.nodeStart=Date.now();pxRender();};
PX_ACTIONS['px-pick']=([i])=>{if(!pxs||pxs.kind!=='scenario'||pxs.phase!=='play'||pxs.locked)return;const sc=PX_SCENARIOS[pxs.id],node=sc.nodes[pxs.node];if(!(i>=0&&i<node.opts.length))return;pxPush();pxs.sel=+i;pxs.rate=null;if(!pxs.conf){pxScenarioLock();}pxRender();if(pxs.conf)requestAnimationFrame(()=>document.querySelector('.px-rate')?.scrollIntoView({block:'nearest',behavior:'auto'}));};
PX_ACTIONS['px-rate']=([n])=>{if(!pxs||pxs.locked||![1,2,3].includes(+n))return;pxPush();pxs.rate=+n;pxRender();};
PX_ACTIONS['px-lock']=()=>{if(!pxs||pxs.locked||pxs.sel===null||(pxs.conf&&!pxs.rate))return;pxPush();pxScenarioLock();pxRender();};
PX_ACTIONS['px-hint']=()=>{if(!pxs||pxs.locked)return;pxPush();pxs.hint=true;pxRender();};
PX_ACTIONS['px-next']=()=>{if(!pxs||!pxs.locked)return;const sc=PX_SCENARIOS[pxs.id],e=pxs.path.at(-1),o=sc.nodes[e.node].opts[e.opt];pxPush();if(o.to==='end'){pxScenarioFinish();}else{pxs.node=o.to;pxs.sel=null;pxs.rate=null;pxs.locked=false;pxs.hint=false;pxs.over=false;pxs.nodeStart=Date.now();pxs.prevMeters={...pxs.meters};}pxRender();};
PX_ACTIONS['px-replay']=()=>{if(!pxs||pxs.kind!=='scenario')return;const id=pxs.id,keep={guided:pxs.guided,timed:pxs.timed,conf:pxs.conf};ui.activitySaved=false;ui.lastSavedAttempt=null;pxStartScenario(id);Object.assign(pxs,keep,{phase:'play',nodeStart:Date.now()});pxRender();};
PX_ACTIONS['px-explore']=()=>{if(!pxs||pxs.kind!=='scenario')return;const sc=PX_SCENARIOS[pxs.id],taken=new Set(pxs.path.map(e=>e.node+':'+e.opt)),lines=[];for(const [nid,n] of Object.entries(sc.nodes))n.opts.forEach((o,i)=>{if(!taken.has(nid+':'+i))lines.push(`<li><b>${esc(n.title)}</b> · ${pxQTag(o.q)}<p>${esc(o.t)}</p><p class="px-cmp-why">${esc(o.then)}</p></li>`);});const box=document.getElementById('pxExplore');if(box){box.remove();return;}document.querySelector('.px-debrief .modal-actions')?.insertAdjacentHTML('beforebegin',`<section class="px-sec" id="pxExplore"><h3>Branches you did not take</h3><p class="field-hint">Every option from this scenario you did not choose this time, and what it would have led to.</p><ul class="px-explore">${lines.join('')}</ul></section>`);};
PX_ACTIONS['px-note']=(a,e,el)=>{if(!pxs||!pxs.finished)return;const v=(el?.value||'').slice(0,400);pxs.note=v;const rec=pxStore().attempts.filter(r=>r.id===pxs.id).at(-1);if(rec){rec.note=v;persistQuiet();}};

/* ---------- 6. SBAR builder with live preview ---------- */
const PX_SB_BUCKETS=[['S','Situation','Who, where, what has changed now.'],['B','Background','Only what helps the listener place it.'],['A','Assessment','What you found, and what you think.'],['R','Request','What you want, by when.']];
function pxSbOpen(id){pxs={kind:'sbar',id,phase:'pick',idx:0,place:{},order:[],sel:null,readback:true,finished:false,done:[],hist:[]};ui.activitySaved=false;ui.lastSavedAttempt=null;ui.history=[];ui.dirty=false;pxRender();}
function pxSbSanitize(x){if(!['pick','build','result'].includes(x.phase)||!Number.isInteger(x.idx)||!PX_SBAR[x.idx])return null;const c=PX_SBAR[x.idx],ids=new Set(c.chips.map(k=>k.id)),place={};for(const [k,v] of Object.entries(x.place||{}))if(ids.has(k)&&['S','B','A','R','x'].includes(v))place[k]=v;
 let order=Array.isArray(x.order)&&x.order.length===c.chips.length&&x.order.every(i=>Number.isInteger(i)&&i>=0&&i<c.chips.length)&&new Set(x.order).size===c.chips.length?x.order:pxShuffle(c.chips.length);
 return {kind:'sbar',id:x.id,phase:x.phase,idx:x.idx,place,order,sel:ids.has(x.sel)?x.sel:null,readback:x.readback!==false,finished:x.phase==='result'&&!!x.finished,done:(Array.isArray(x.done)?x.done:[]).filter(i=>Number.isInteger(i)&&PX_SBAR[i]),hist:[]};}
function pxSbCase(){return PX_SBAR[pxs.idx];}
function pxSbWords(t){return (t.match(/\S+/g)||[]).length;}
function pxSbMessage(){const c=pxSbCase(),s=pxs,parts=[c.opener];for(const [k] of PX_SB_BUCKETS)for(const ch of c.chips)if(s.place[ch.id]===k)parts.push(ch.t);if(s.readback)parts.push('Could you read that back to me so I know we are on the same page?');return parts;}
function pxSbChecks(){const c=pxSbCase(),s=pxs,inb=k=>c.chips.filter(ch=>s.place[ch.id]===k),all=PX_SB_BUCKETS.flatMap(([k])=>inb(k));
 return [['Opens with who, where and what has changed',inb('S').some(ch=>ch.cat==='S')],['Gives a measurement alongside the earlier value',inb('A').some(ch=>/\d/.test(ch.t)&&/\(|was|from/i.test(ch.t))],['Says your concern in words',all.some(ch=>/worried|concern/i.test(ch.t))],['Makes a specific request with a time',inb('R').some(ch=>ch.cat==='R'&&!ch.weak)],['Leaves out what the listener does not need',all.length>0&&!all.some(ch=>ch.cat==='n')],['Invites a read-back',!!s.readback]];}
function pxSbChipHTML(ch,where){const s=pxs,sel=s.sel===ch.id;return `<li class="px-sbchip${sel?' is-sel':''}"><button type="button" class="px-chipcard" aria-pressed="${sel}" draggable="true" data-ondragstart="px-drag" data-action="px-sb-sel" data-arg0="${ch.id}"><span>${esc(ch.t)}</span></button>${sel?`<div class="px-place" role="group" aria-label="Move this note to"><span class="px-pref-l">Place in</span>${PX_SB_BUCKETS.map(([k,n])=>`<button type="button" class="btn secondary px-placebtn${s.place[ch.id]===k?' on':''}" data-action="px-sb-place" data-arg0="${ch.id}" data-arg1="${k}"><b>${k}</b> ${n}</button>`).join('')}<button type="button" class="btn secondary px-placebtn${s.place[ch.id]==='x'?' on':''}" data-action="px-sb-place" data-arg0="${ch.id}" data-arg1="x">Leave out</button>${where?`<button type="button" class="btn ghost px-placebtn" data-action="px-sb-place" data-arg0="${ch.id}" data-arg1="">Back to my notes</button>`:''}</div>`:''}</li>`;}
function pxSbRender(){const s=pxs;let body;if(s.phase==='pick')body=pxSbPick();else if(s.phase==='build')body=pxSbBuild();else body=pxSbResult();pxShowPx('px-sbar',body);
 requestAnimationFrame(()=>{const d=document.getElementById('modal');const t=s.phase==='result'?d.querySelector('.px-outcome'):s.phase==='pick'?d.querySelector('.px-setup h3'):(s.sel?d.querySelector('.px-chipcard[aria-pressed="true"]'):d.querySelector('.px-tray .px-chipcard')||d.querySelector('[data-action="px-sb-check"]'));if(t){if(!t.matches('button'))t.tabIndex=-1;t.focus({preventScroll:true});}});}
function pxShowPx(id,body,subtitle){const a=pxActivity(id),m=PX_META[id],d=document.getElementById('modal'),st=d.open?d.scrollTop:0;showModal(esc(a.title),subtitle||`Fictional practice · ${pxLevel(m.level).name} · about ${m.min} min`,body);d.classList.add('tool-workspace','px-modal');if(st)d.scrollTop=st;}
function pxSbPick(){const s=pxs;return `<div class="px-setup">${pxBriefHTML(s.id,{open:!s.done.length,how:'Sort the notes into Situation, Background, Assessment and Request. The message builds as you work, with live checks on how it will sound.'})}<section class="px-card"><h3>Choose a build</h3><p>Each build is a different fictional patient and a different level of noise. Start where it feels right.</p><div class="px-cases">${PX_SBAR.map((c,i)=>`<button type="button" class="px-casecard" data-action="px-sb-start" data-arg0="${i}">${pxLevelBadge(c.level)}<strong>${esc(c.title)}</strong><span>${c.chips.length} notes${s.done.includes(i)?' · done':''}</span></button>`).join('')}</div></section></div>`;}
function pxSbBuild(){const s=pxs,c=pxSbCase(),unplaced=s.order.map(i=>c.chips[i]).filter(ch=>!s.place[ch.id]),left=c.chips.filter(ch=>s.place[ch.id]==='x'),msg=pxSbMessage(),words=msg.join(' ').split(/\s+/).length,secs=Math.round(words/2.4),checks=pxSbChecks();
 return `<div class="px-sbar"><p class="px-lead">${esc(c.intro)}</p><div class="px-sbgrid"><div class="px-sbleft"><section class="px-card px-tray" aria-label="Your notes"><h3>Your notes <small>(${unplaced.length} to place)</small></h3>${unplaced.length?`<ul class="px-sblist">${unplaced.map(ch=>pxSbChipHTML(ch,false)).join('')}</ul>`:'<p class="field-hint">All notes placed. Review the message, then check it.</p>'}<p class="field-hint">Tap a note, then choose where it goes. On a computer you can also drag it onto a box.</p></section>
 <div class="px-buckets">${PX_SB_BUCKETS.map(([k,n,h])=>{const items=c.chips.filter(ch=>s.place[ch.id]===k);return `<section class="px-bucket" data-ondragover="px-dragover" data-ondragleave="px-dragleave" data-ondrop="px-drop" data-arg0="${k}" aria-label="${n}"><h4><b>${k}</b> ${n}</h4><p class="field-hint">${h}</p>${items.length?`<ul class="px-sblist">${items.map(ch=>pxSbChipHTML(ch,true)).join('')}</ul>`:'<p class="px-empty">Nothing here yet</p>'}</section>`;}).join('')}<section class="px-bucket px-leaveout" data-ondragover="px-dragover" data-ondragleave="px-dragleave" data-ondrop="px-drop" data-arg0="x" aria-label="Left out"><h4>Left out</h4><p class="field-hint">Not needed on this call.</p>${left.length?`<ul class="px-sblist">${left.map(ch=>pxSbChipHTML(ch,true)).join('')}</ul>`:'<p class="px-empty">Nothing left out yet</p>'}</section></div></div>
 <aside class="px-sbright" aria-label="Live preview"><section class="px-card px-preview"><h3>The message as they hear it</h3><p class="px-script">${msg.map((t,i)=>`<span class="${i===0?'px-open':''}">${esc(t)}</span>`).join(' ')}</p><div class="px-time" role="img" aria-label="About ${secs} seconds to say aloud"><span style="width:${pxClamp(secs*2.2,4,100)}%"></span></div><p class="field-hint">About ${words} words, roughly ${secs} seconds aloud. A short call is easier to follow.</p><label class="px-check"><input type="checkbox" ${s.readback?'checked':''} data-onchange="px-sb-readback"> End by asking them to read it back</label></section>
 <section class="px-card"><h3>Live checks</h3><ul class="px-checks">${checks.map(([t,ok])=>`<li class="${ok?'ok':''}"><span aria-hidden="true">${ok?'✓':'○'}</span><span>${esc(t)}<span class="px-sr">${ok?' (met)':' (not yet)'}</span></span></li>`).join('')}</ul></section><div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-sb-check" ${unplaced.length?'disabled':''}>${unplaced.length?`Place ${unplaced.length} more note${unplaced.length>1?'s':''} to check`:'Check my message →'}</button></div></aside></div></div>`;}
function pxSbVerdict(ch){const p=pxs.place[ch.id];if(ch.cat==='n')return p==='x'?'good':'noise';if(ch.weak&&ch.cat==='R')return p==='x'?'good':p==='R'?'weak':'moved';if(p===ch.cat||(ch.alt||[]).includes(p))return 'good';if(p==='x')return 'missed';return 'moved';}
const PX_VERDICT={good:['Well judged','best'],noise:['Noise included','risk'],weak:['Vague request used','risk'],moved:['Wrong place','ok'],missed:['Left out, but needed','risk']};
function pxSbScore(){const c=pxSbCase(),v=c.chips.map(ch=>[ch,pxSbVerdict(ch)]),good=v.filter(x=>x[1]==='good').length;return {v,good,total:c.chips.length};}
function pxSbResult(){const s=pxs,c=pxSbCase(),R=pxSbScore(),msg=pxSbMessage(),ideal=[c.opener,...PX_SB_BUCKETS.flatMap(([k])=>c.chips.filter(ch=>ch.cat===k&&!ch.weak).map(ch=>ch.t)),'Could you read that back to me so I know we are on the same page?'];
 const lane=(k,n)=>`<div class="px-lane"><h4><b>${k}</b> ${n}</h4>${R.v.filter(([ch])=>s.place[ch.id]===k).map(([ch,v])=>`<div class="px-dot q-${PX_VERDICT[v][1]}">${pxQGlyph(PX_VERDICT[v][1],16)}<span>${esc(ch.t)}</span></div>`).join('')||'<p class="px-empty">Empty</p>'}</div>`;
 const strongEnough=R.good>=Math.ceil(R.total*.8);
 return `<div class="px-debrief"><section class="px-outcome px-outcome-${strongEnough?'strong':R.good>=Math.ceil(R.total*.6)?'mixed':'weak'}"><span class="eyebrow">YOUR MESSAGE</span><h3>${R.good} of ${R.total} notes were well judged</h3><p>${strongEnough?'This message would be heard quickly and acted on. The listener knows who, what has changed, how worried you are and what you want.':'There is something to sharpen. The detail below shows which notes were in the wrong place, were noise, or were missing.'}</p></section>
 <section class="px-sec"><h3>Where your notes landed</h3><div class="px-lanes">${PX_SB_BUCKETS.map(([k,n])=>lane(k,n)).join('')}${`<div class="px-lane px-lane-out"><h4>Left out</h4>${R.v.filter(([ch])=>s.place[ch.id]==='x').map(([ch,v])=>`<div class="px-dot q-${PX_VERDICT[v][1]}">${pxQGlyph(PX_VERDICT[v][1],16)}<span>${esc(ch.t)}</span></div>`).join('')||'<p class="px-empty">Nothing</p>'}</div>`}</div><p class="px-legend-line">${['best','ok','risk'].map(q=>`<span>${pxQGlyph(q,16)}${q==='best'?'Well judged':q==='ok'?'Wrong place':'Noise, vague or missing'}</span>`).join('')}</p></section>
 <section class="px-sec"><h3>Note by note</h3><ul class="px-verdicts">${R.v.map(([ch,v])=>`<li class="q-${PX_VERDICT[v][1]}">${pxQTag(PX_VERDICT[v][1]).replace(PX_Q[PX_VERDICT[v][1]][0],PX_VERDICT[v][0])}<p>${esc(ch.t)}</p><p class="px-cmp-why">${esc(ch.why)}</p>${v==='moved'||v==='missed'?`<p class="px-cmp-why"><b>Belongs in</b> ${PX_SB_BUCKETS.find(b=>b[0]===ch.cat)?.[1]||'—'}.</p>`:''}</li>`).join('')}</ul></section>
 <section class="px-sec"><h3>Your message and a stronger version</h3><div class="px-two"><div class="px-card"><h4>Yours</h4><p class="px-script">${msg.map(t=>esc(t)).join(' ')}</p></div><div class="px-card px-model"><h4>Stronger</h4><p class="px-script">${ideal.map(t=>esc(t)).join(' ')}</p></div></div></section>
 <section class="px-sec px-take"><h3>Take-aways</h3>${pxList(['Lead with who, where and what has changed. The first sentence decides whether the listener is paying attention.','Put the earlier value next to the new one. Direction of change is the information.','Make the request specific and give it a time. “When you get a chance” is not a plan.','Leave out the true but irrelevant. Noise dilutes the signal.'])}</section>
 <p class="px-saved" role="status">${icon('check')}Saved to My Growth.</p>
 <div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-sb-again">Try another build →</button></div></div>`;}
PX_ENGINES.sbar={open:pxSbOpen,render:pxSbRender,sanitize:pxSbSanitize};
PX_ACTIONS['px-sb-start']=([i])=>{if(!pxs||pxs.kind!=='sbar'||!PX_SBAR[+i])return;pxPush();pxs.idx=+i;pxs.phase='build';pxs.place={};pxs.sel=null;pxs.finished=false;pxs.order=pxShuffle(PX_SBAR[+i].chips.length);ui.activitySaved=false;ui.lastSavedAttempt=null;pxRender();};
PX_ACTIONS['px-sb-sel']=([id])=>{if(!pxs||pxs.phase!=='build')return;pxs.sel=pxs.sel===id?null:id;pxRender();};
function pxSbPlace(id,k){const c=pxSbCase();if(!c.chips.some(ch=>ch.id===id))return;pxPush();if(k==='')delete pxs.place[id];else if(['S','B','A','R','x'].includes(k))pxs.place[id]=k;else return;pxs.sel=null;pxRender();}
PX_ACTIONS['px-sb-place']=([id,k])=>{if(!pxs||pxs.phase!=='build')return;pxSbPlace(id,k);};
PX_ACTIONS['px-sb-readback']=(a,e,el)=>{if(!pxs||pxs.phase!=='build')return;pxPush();pxs.readback=!!el.checked;pxRender();};
PX_ACTIONS['px-drag']=(a,e)=>{if(!pxs||pxs.kind!=='sbar'||pxs.phase!=='build'||!e.dataTransfer)return;e.dataTransfer.setData('text/plain','carecraft-px:'+a[0]);e.dataTransfer.effectAllowed='move';};
PX_ACTIONS['px-dragover']=(a,e,el)=>{e.preventDefault();el.classList.add('over');};
PX_ACTIONS['px-dragleave']=(a,e,el)=>{el.classList.remove('over');};
PX_ACTIONS['px-drop']=(a,e,el)=>{e.preventDefault();el.classList.remove('over');const t=e.dataTransfer?.getData('text/plain')||'';if(!t.startsWith('carecraft-px:')||!pxs||pxs.phase!=='build')return;pxSbPlace(t.slice(13),a[0]);};
PX_ACTIONS['px-sb-check']=()=>{if(!pxs||pxs.phase!=='build')return;const c=pxSbCase();if(c.chips.some(ch=>!pxs.place[ch.id])){toast('Place every note, or leave it out, before checking.');return;}pxPush();const R=pxSbScore();pxs.phase='result';pxs.finished=true;if(!pxs.done.includes(pxs.idx))pxs.done.push(pxs.idx);
 pxRecord({id:pxs.id,kind:'sbar',date:pxNow(),level:c.level,mode:{},strong:R.good,ok:0,risk:R.total-R.good,total:R.total,case:c.id,secs:0});
 const msg=pxSbMessage().join(' ');ui.activitySaved=false;logStudio(pxs.id,pxActivity(pxs.id).title+' · '+c.title,`${R.good} of ${R.total} notes were well judged. Level: ${pxLevel(c.level).name}.\n\nMy message:\n${msg}\n\nOriginal fictional exercise. A learning record, not a measure of clinical competence.`);pxRender();};
PX_ACTIONS['px-sb-again']=()=>{if(!pxs||pxs.kind!=='sbar')return;pxPush();pxs.phase='pick';pxs.finished=false;pxs.sel=null;ui.activitySaved=false;pxRender();};

/* ---------- 7. Escalation ladder ---------- */
const PX_URG={immediate:['Immediate','risk'],soon:['Soon','ok'],routine:['Routine','best']};
function pxLdOpen(id){pxs={kind:'ladder',id,phase:'play',i:0,rung:null,say:null,locked:false,results:[],order:{},finished:false,hist:[]};ui.activitySaved=false;ui.lastSavedAttempt=null;ui.history=[];ui.dirty=false;pxRender();}
function pxLdSanitize(x){if(!['play','result'].includes(x.phase)||!Number.isInteger(x.i)||x.i<0||x.i>PX_LADDER.length)return null;const results=[];for(const r of x.results||[]){const c=PX_LADDER.find(k=>k.id===r.id);if(!c||!PX_RUNGS.some(g=>g.id===r.rung)||!Number.isInteger(r.say)||!c.say[r.say])return null;results.push({id:r.id,rung:r.rung,say:r.say});}
 const order={};for(const [k,v] of Object.entries(x.order||{}))if(PX_LADDER.some(c=>c.id===k)&&Array.isArray(v)&&v.length===3&&new Set(v).size===3&&v.every(n=>[0,1,2].includes(n)))order[k]=v;
 const c=PX_LADDER[x.i];const rung=c&&PX_RUNGS.some(g=>g.id===x.rung)?x.rung:null,say=c&&[0,1,2].includes(x.say)?x.say:null;
 return {kind:'ladder',id:x.id,phase:x.phase,i:x.i,rung,say,locked:!!x.locked&&say!==null,results,order,finished:x.phase==='result'&&!!x.finished,hist:[]};}
function pxLdQ(c,r){return c.ideal.includes(r)?'best':c.ok.includes(r)?'ok':'risk';}
function pxLdRender(){const s=pxs;let body;if(s.phase==='result')body=pxLdResult();else body=pxLdPlay();pxShowPx(s.id,body);requestAnimationFrame(()=>{const d=document.getElementById('modal');const t=s.phase==='result'?d.querySelector('.px-outcome'):s.locked?d.querySelector('.px-feedback'):d.querySelector('.px-q');if(t){t.tabIndex=-1;t.focus({preventScroll:false});}});}
function pxLdPlay(){const s=pxs,c=PX_LADDER[s.i],locked=s.locked,rungChosen=s.rung!==null;const order=(s.order[c.id]=s.order[c.id]||pxShuffle(3));const u=PX_URG[c.urgency];
 const ladder=`<ol class="px-ladder" aria-label="Escalation ladder: choose where you would go first">${PX_RUNGS.map(g=>{const chosen=s.rung===g.id,ideal=locked&&c.ideal.includes(g.id),okr=locked&&c.ok.includes(g.id);return `<li class="px-rung${chosen?' is-chosen':''}${ideal?' is-ideal':''}"><button type="button" class="px-rungbtn" aria-pressed="${chosen}" ${locked?'disabled':''} data-action="px-ld-rung" data-arg0="${g.id}"><span class="px-rungn">${g.id}</span><span class="px-rungt"><strong>${esc(g.t)}</strong><small>${esc(g.d)}</small></span>${locked?`<span class="px-rungmark">${chosen?`<span class="px-chip">Your choice</span>`:''}${ideal?`<span class="px-chip px-chip-good">${pxQGlyph('best',14)}Suggested</span>`:okr?'<span class="px-chip">Also reasonable</span>':''}</span>`:''}</button></li>`;}).join('')}</ol>`;
 const say=rungChosen?`<h3 class="px-q" id="pxLdSay">What do you say?</h3><div class="px-opts answer-list" role="group" aria-label="What you say">${order.map((oi,di)=>{const o=c.say[oi],isSel=s.say===oi,cls=locked?(o.q==='best'?'correct':isSel?'incorrect':''):'';return `<button type="button" class="answer px-opt ${isSel?'is-selected':''} ${cls}" aria-pressed="${isSel}" ${locked?'disabled':''} data-action="px-ld-say" data-arg0="${oi}"><span class="letter">${'ABC'[di]}</span><span class="px-opt-t">${esc(o.t)}</span>${locked?`<span class="px-opt-q q-${o.q}">${pxQGlyph(o.q,18)}<span class="px-sr">${PX_Q[o.q][0]}</span>${isSel?'<small>Your choice</small>':''}</span>`:''}</button>`;}).join('')}</div>`:'';
 let fb='';if(locked){const rq=pxLdQ(c,s.rung),sq=c.say[s.say].q;fb=`<section class="px-feedback q-${rq==='best'&&sq==='best'?'best':rq==='risk'||sq==='risk'?'risk':'ok'}" aria-live="polite"><div class="px-fb-head">${pxQGlyph(rq,30)}<div><strong>Rung: ${PX_Q[rq][0]}</strong></div></div><p>${esc(c.why)}</p><p class="px-then"><b>On skipping rungs.</b> ${esc(c.skip)}</p><div class="px-fb-head">${pxQGlyph(sq,30)}<div><strong>Words: ${PX_Q[sq][0]}</strong></div></div><p>${esc(c.say[s.say].why)}</p>${sq!=='best'?`<details open><summary>A stronger way to say it</summary><p>${esc(c.say.find(o=>o.q==='best').t)}</p></details>`:''}</section><div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-ld-next">${s.i===PX_LADDER.length-1?'See my ladder map':'Next situation'} →</button></div>`;}
 return `<div class="px-play px-ladderplay"><div class="px-progress"><span>Situation ${s.i+1} of ${PX_LADDER.length}</span><span class="px-pips-lg" aria-hidden="true">${PX_LADDER.map((_,i)=>`<i class="${i<s.i?'done':i===s.i?'now':''}"></i>`).join('')}</span></div><article class="px-scene"><div class="px-scene-top"><h3 class="px-scene-t">${esc(c.title)}</h3><span class="px-tag q-${u[1]}">Urgency: ${u[0]}</span></div><p>${esc(c.scene)}</p></article><h3 class="px-q">Where do you go first?</h3><p class="field-hint">Rungs are not a strict sequence. Urgency decides whether to climb or to skip.</p>${ladder}${say}${fb}</div>`;}
function pxLdMap(){const W=Math.max(360,PX_LADDER.length*110),H=230,x=i=>56+i*(W-92)/(PX_LADDER.length-1),y=r=>H-36-(r-1)*(H-72)/4;let svg=`<svg class="px-ldmap" viewBox="0 0 ${W} ${H}" role="img" aria-label="Ladder map: for each situation, the rung you chose and the suggested rung">`;
 for(let r=1;r<=5;r++)svg+=`<line class="px-grid" x1="40" x2="${W-8}" y1="${y(r)}" y2="${y(r)}"/><text x="10" y="${y(r)+4}" class="px-axis">${r}</text>`;
 pxs.results.forEach((res,i)=>{const c=PX_LADDER.find(k=>k.id===res.id),ideal=c.ideal[0];svg+=`<text x="${x(i)}" y="${H-10}" text-anchor="middle" class="px-nlabel">${i+1}</text>`;if(res.rung!==ideal)svg+=`<line class="px-gap" x1="${x(i)}" x2="${x(i)}" y1="${y(res.rung)}" y2="${y(ideal)}"/>`;svg+=c.ideal.map(r=>`<circle class="px-ring" cx="${x(i)}" cy="${y(r)}" r="12"/>`).join('')+`<g transform="translate(${x(i)} ${y(res.rung)})" class="px-n q-${pxLdQ(c,res.rung)}"><circle r="9"/></g>`;});
 return svg+'</svg>';}
function pxLdResult(){const s=pxs,rows=s.results.map(r=>{const c=PX_LADDER.find(k=>k.id===r.id),rq=pxLdQ(c,r.rung),sq=c.say[r.say].q;return {c,r,rq,sq,q:rq==='best'&&sq==='best'?'best':rq==='risk'||sq==='risk'?'risk':'ok'};}),strong=rows.filter(r=>r.q==='best').length;
 return `<div class="px-debrief"><section class="px-outcome px-outcome-${strong>=4?'strong':strong>=2?'mixed':'weak'}"><span class="eyebrow">YOUR LADDER MAP</span><h3>${strong} of ${rows.length} situations: right rung and strong words</h3><p>The rung you choose should follow the urgency, not a fixed order. Strong wording names what you see and what you want.</p></section>
 <section class="px-sec"><h3>Where you went, and where it made sense to go</h3><figure class="px-pathmap"><div class="px-pathscroll">${pxLdMap()}</div><figcaption class="px-legend"><span>${pxQGlyph('best',16)}Your rung (filled)</span><span><svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" class="px-ring-i"><circle cx="12" cy="12" r="9"/></svg>Suggested rung (ring)</span></figcaption></figure><ul class="px-verdicts">${rows.map((x,i)=>`<li class="q-${x.q}"><b>${i+1}. ${esc(x.c.title)}</b> ${pxQTag(x.q)}<p>Rung ${x.r.rung} (${PX_Q[x.rq][0].toLowerCase()}); suggested ${x.c.ideal.join(' or ')}. Words: ${PX_Q[x.sq][0].toLowerCase()}.</p></li>`).join('')}</ul></section>
 <section class="px-sec px-take"><h3>Take-aways</h3>${pxList(['Immediate risk: go to the fastest route that can act, which may skip rungs entirely.','If your first escalation does not work, go again to someone with authority to act. Say what has changed since.','Say what you see, how you feel about it, and what you want. “I am concerned, this is a safety issue” is CUS.','A system problem is a formal report, not a workaround.'])}</section><p class="px-saved" role="status">${icon('check')}Saved to My Growth.</p>
 <div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-ld-again">Try the ladder again →</button></div></div>`;}
PX_ENGINES.ladder={open:pxLdOpen,render:pxLdRender,sanitize:pxLdSanitize};
PX_ACTIONS['px-ld-rung']=([r])=>{if(!pxs||pxs.kind!=='ladder'||pxs.locked||!PX_RUNGS.some(g=>g.id===+r))return;pxPush();pxs.rung=+r;pxRender();requestAnimationFrame(()=>document.getElementById('pxLdSay')?.scrollIntoView({block:'nearest',behavior:studioReducedMotion()?'auto':'smooth'}));};
PX_ACTIONS['px-ld-say']=([n])=>{if(!pxs||pxs.kind!=='ladder'||pxs.locked||pxs.rung===null||![0,1,2].includes(+n))return;pxPush();pxs.say=+n;pxs.locked=true;pxs.results=pxs.results.filter(r=>r.id!==PX_LADDER[pxs.i].id);pxs.results.push({id:PX_LADDER[pxs.i].id,rung:pxs.rung,say:+n});pxRender();};
PX_ACTIONS['px-ld-next']=()=>{if(!pxs||!pxs.locked)return;pxPush();if(pxs.i>=PX_LADDER.length-1){pxs.phase='result';pxs.finished=true;pxs.results.sort((a,b)=>PX_LADDER.findIndex(c=>c.id===a.id)-PX_LADDER.findIndex(c=>c.id===b.id));
  const rows=pxs.results.map(r=>{const c=PX_LADDER.find(k=>k.id===r.id),rq=pxLdQ(c,r.rung),sq=c.say[r.say].q;return {c,r,rq,sq,q:rq==='best'&&sq==='best'?'best':rq==='risk'||sq==='risk'?'risk':'ok'};}),strong=rows.filter(r=>r.q==='best').length,risk=rows.filter(r=>r.q==='risk').length;
  pxRecord({id:pxs.id,kind:'ladder',date:pxNow(),level:PX_META[pxs.id].level,mode:{},strong,ok:rows.length-strong-risk,risk,total:rows.length,secs:0});ui.activitySaved=false;logStudio(pxs.id,pxActivity(pxs.id).title,`${strong} of ${rows.length} situations: right rung and strong words.\n\n`+rows.map((x,i)=>`${i+1}. ${x.c.title}\nChose rung ${x.r.rung}; suggested ${x.c.ideal.join(' or ')}.\nSaid: ${x.c.say[x.r.say].t}`).join('\n\n')+'\n\nOriginal fictional exercise. A learning record, not a measure of clinical competence.');}else{pxs.i++;pxs.rung=null;pxs.say=null;pxs.locked=false;}pxRender();};
PX_ACTIONS['px-ld-again']=()=>{if(!pxs||pxs.kind!=='ladder')return;pxLdOpen(pxs.id);};

/* ---------- 8. Prioritising, with drag-and-drop and tap alternatives ---------- */
/* labels: items in the intended order. yours: for each position the learner chose, the index (in labels) they placed there. */
function pxSeqCompare(labels,yours,opts={}){const n=labels.length,posOf=i=>yours.indexOf(i),rowH=60;
 const diff=i=>posOf(i)-i;const tone=d=>d===0?'best':Math.abs(d)===1?'ok':'risk';
 const table=`<div class="px-tablewrap"><table class="px-seqtable"><caption>${esc(opts.caption||'Your order against the suggested order')}</caption><thead><tr><th scope="col">Suggested</th><th scope="col">Item</th><th scope="col">Your place</th><th scope="col">Difference</th></tr></thead><tbody>${labels.map((l,i)=>{const d=diff(i);return `<tr class="q-${tone(d)}"><th scope="row">${i+1}</th><td>${esc(l)}</td><td>${posOf(i)+1}</td><td>${d===0?'Same place':(d>0?'You placed it '+d+' later':'You placed it '+(-d)+' earlier')}</td></tr>`;}).join('')}</tbody></table></div>`;
 const map=`<div class="px-seqmap" aria-hidden="true" style="--rows:${n};--rowh:${rowH}px"><ol class="px-seqcol">${yours.map(i=>`<li>${esc(labels[i])}</li>`).join('')}</ol><svg viewBox="0 0 100 ${n*rowH}" preserveAspectRatio="none">${labels.map((l,i)=>{const y1=posOf(i)*rowH+rowH/2,y2=i*rowH+rowH/2;return `<path class="q-${tone(diff(i))}" d="M0 ${y1}C45 ${y1} 55 ${y2} 100 ${y2}" fill="none" vector-effect="non-scaling-stroke"/>`;}).join('')}</svg><ol class="px-seqcol">${labels.map(l=>`<li>${esc(l)}</li>`).join('')}</ol></div><div class="px-seqcap" aria-hidden="true"><span>Your order</span><span>Suggested order</span></div>`;
 return `<figure class="px-seqfig">${map}${table}</figure>`;}
function pxPrOpen(id){const order=PX_PRIORITY.map(r=>pxShuffle(r.tasks.length).map(i=>r.tasks[i].id));pxs={kind:'priority',id,phase:'pick',r:0,orders:order,revealed:false,notes:{},results:{},finished:false,hist:[]};ui.activitySaved=false;ui.lastSavedAttempt=null;ui.history=[];ui.dirty=false;pxRender();}
function pxPrSanitize(x){if(!['pick','play','result'].includes(x.phase)||!Number.isInteger(x.r)||!PX_PRIORITY[x.r]||!Array.isArray(x.orders)||x.orders.length!==PX_PRIORITY.length)return null;const orders=[];for(let i=0;i<PX_PRIORITY.length;i++){const ids=PX_PRIORITY[i].tasks.map(t=>t.id),o=x.orders[i];if(!Array.isArray(o)||o.length!==ids.length||new Set(o).size!==ids.length||!o.every(k=>ids.includes(k)))return null;orders.push(o);}
 const results={};for(const [k,v] of Object.entries(x.results||{}))if(PX_PRIORITY.some(r=>r.id===k)&&v&&typeof v==='object')results[k]={q:['best','ok','risk'].includes(v.q)?v.q:'ok',exact:+v.exact||0,key:!!v.key};const notes={};for(const [k,v] of Object.entries(x.notes||{}))if(PX_PRIORITY.some(r=>r.id===k)&&typeof v==='string')notes[k]=v.slice(0,300);
 return {kind:'priority',id:x.id,phase:x.phase,r:x.r,orders,revealed:!!x.revealed,notes,results,finished:x.phase==='result'&&!!x.finished,hist:[]};}
function pxPrRender(){const s=pxs;let body;if(s.phase==='pick')body=pxPrPick();else if(s.phase==='result')body=pxPrResult();else body=pxPrPlay();pxShowPx(s.id,body);requestAnimationFrame(()=>{const d=document.getElementById('modal'),t=s.phase==='result'?d.querySelector('.px-outcome'):s.phase==='pick'?d.querySelector('.px-setup h3'):s.revealed?d.querySelector('.px-feedback'):d.querySelector('.px-q');if(t){t.tabIndex=-1;t.focus({preventScroll:true});}});}
function pxPrPick(){const s=pxs;return `<div class="px-setup">${pxBriefHTML(s.id,{open:true,how:'Put the tasks in the order you would do them, using drag and drop or the move buttons. Then compare with a worked rationale. Reasonable people differ on some places; the key judgement is flagged.'})}<section class="px-card"><h3>Choose a round</h3><div class="px-cases">${PX_PRIORITY.map((r,i)=>`<button type="button" class="px-casecard" data-action="px-pr-start" data-arg0="${i}">${pxLevelBadge(r.level)}<strong>${esc(r.title.replace(/^Round \d: /,''))}</strong><span>${r.tasks.length} tasks${s.results[r.id]?' · done':''}</span></button>`).join('')}</div></section><section class="px-card"><h3>Four questions that help</h3>${pxPrQuestions()}</section></div>`;}
function pxPrQuestions(){return `<ol class="px-fourq"><li><b>Is anyone at immediate risk?</b> Go first, and call for help through the local route.</li><li><b>What is time-critical?</b> A fixed window, or a person waiting in distress.</li><li><b>What is blocking others?</b> A short task that unblocks a colleague may be worth doing early.</li><li><b>Who can help or take this?</b> Asking for help early is a priority skill, not a failure.</li></ol><p class="field-hint">These are teaching prompts written for this exercise. Your own local protocols and what you can see take precedence.</p>`;}
function pxPrPlay(){const s=pxs,rd=PX_PRIORITY[s.r],order=s.orders[s.r],byId=Object.fromEntries(rd.tasks.map(t=>[t.id,t]));
 const list=order.map((id,i)=>{const t=byId[id];return `<li class="px-task" draggable="${!s.revealed}" data-ondragstart="px-pr-drag" data-ondragover="px-pr-over" data-ondragleave="px-dragleave" data-ondrop="px-pr-drop" data-arg0="${id}"><span class="px-tasknum" aria-hidden="true">${i+1}</span><span class="px-tasktext">${esc(t.t)}</span><span class="px-taskbtns"><button type="button" class="btn secondary px-move" aria-label="Move up: ${esc(t.t)}" ${i===0||s.revealed?'disabled':''} data-action="px-pr-move" data-arg0="${id}" data-arg1="-1">↑<span class="px-sr"> Move up</span></button><button type="button" class="btn secondary px-move" aria-label="Move down: ${esc(t.t)}" ${i===order.length-1||s.revealed?'disabled':''} data-action="px-pr-move" data-arg0="${id}" data-arg1="1">↓<span class="px-sr"> Move down</span></button></span></li>`;}).join('');
 let fb='';if(s.revealed){const yours=order.map(id=>rd.tasks.findIndex(t=>t.id===id)),R=pxPrScore(s.r);fb=`<section class="px-feedback q-${R.q}" aria-live="polite"><div class="px-fb-head">${pxQGlyph(R.q,30)}<div><strong>${R.key?'The key judgement is first.':'The key judgement was not first.'}</strong></div></div><p>${R.key?'You put the person who may be at immediate risk first. That is the judgement everything else depends on.':'The task that may involve immediate risk should come first, whatever else is pending. Everything else can wait a moment, or be handed on.'}</p><p>${R.exact} of ${rd.tasks.length} tasks are in a reasonable place.</p>${pxSeqCompare(rd.tasks.map(t=>t.t),yours,{caption:'Your order against the suggested order'})}<h4>The reasoning</h4><ol class="px-rationale">${rd.tasks.slice().sort((a,b)=>a.rank-b.rank).map(t=>`<li><b>${t.rank}.</b> ${esc(t.t)}<p class="px-cmp-why">${esc(t.why)}${t.alt?` <i>Places ${t.alt.join(' to ')} are also reasonable.</i>`:''}</p></li>`).join('')}</ol><label for="pxPrNote">What would change your order? <span class="field-hint">Optional. Stays on this device.</span></label><textarea id="pxPrNote" rows="2" maxlength="300" data-oninput="px-pr-note">${esc(s.notes[rd.id]||'')}</textarea></section><div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-pr-next">${PX_PRIORITY.every(r=>s.results[r.id])?'See my summary':'Back to the rounds'} →</button></div>`;}
 return `<div class="px-play"><article class="px-scene"><div class="px-scene-top"><h3 class="px-scene-t">${esc(rd.title)}</h3>${pxLevelBadge(rd.level)}</div><p>${esc(rd.scene)}</p></article><details class="px-cue"${rd.level==='foundation'?' open':''}><summary>Four questions that help</summary>${pxPrQuestions()}</details><h3 class="px-q">Put these in the order you would do them</h3><p class="field-hint">${s.revealed?'Your order is locked. Read the reasoning below.':'Drag a task, or use the arrows. First place is the top.'}</p><ol class="px-tasks" aria-label="Tasks, first to last">${list}</ol>${s.revealed?'':`<div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-pr-check">Check my order →</button></div>`}${fb}</div>`;}
function pxPrScore(r){const s=pxs,rd=PX_PRIORITY[r],order=s.orders[r],pos=id=>order.indexOf(id)+1,keyT=rd.tasks.find(t=>t.key),key=order[0]===keyT.id;let exact=0;for(const t of rd.tasks){const p=pos(t.id);if(p===t.rank||(t.alt||[]).includes(p))exact++;}const q=!key?'risk':exact>=rd.tasks.length-1?'best':exact>=rd.tasks.length-3?'ok':'risk';return {key,exact,q};}
function pxPrResult(){const s=pxs,rows=PX_PRIORITY.map(r=>({r,res:s.results[r.id]})).filter(x=>x.res),strong=rows.filter(x=>x.res.q==='best').length;
 return `<div class="px-debrief"><section class="px-outcome px-outcome-${strong>=2?'strong':strong>=1?'mixed':'weak'}"><span class="eyebrow">YOUR PRIORITISING</span><h3>${rows.filter(x=>x.res.key).length} of ${rows.length} rounds: the key judgement came first</h3><p>Putting the person who may be at risk first is the thing everything else hangs on. The rest is judgement, which varies, and which asking for help can ease.</p></section><section class="px-sec"><h3>Round by round</h3><ul class="px-verdicts">${rows.map(x=>`<li class="q-${x.res.q}"><b>${esc(x.r.title.replace(/^Round \d: /,''))}</b> ${pxQTag(x.res.q)}<p>${x.res.exact} of ${x.r.tasks.length} tasks in a reasonable place. ${x.res.key?'Key judgement first.':'Key judgement was not first.'}</p>${s.notes[x.r.id]?`<p class="px-cmp-why"><b>What would change my order:</b> ${esc(s.notes[x.r.id])}</p>`:''}</li>`).join('')}</ul></section><section class="px-sec px-take"><h3>Take-aways</h3>${pxList(['Immediate risk first, whatever else is pending. Then time-critical, then what is blocking others.','Asking for help is part of prioritising. Name what you cannot do and who might.','Reasonable people order the middle differently. Say your reasoning aloud and be ready to change it.','Look after yourself: a delayed break is also a safety factor.'])}</section><p class="px-saved" role="status">${icon('check')}Saved to My Growth.</p><div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-pr-again">Choose another round →</button></div></div>`;}
PX_ENGINES.priority={open:pxPrOpen,render:pxPrRender,sanitize:pxPrSanitize};
PX_ACTIONS['px-pr-start']=([i])=>{if(!pxs||pxs.kind!=='priority'||!PX_PRIORITY[+i])return;pxPush();pxs.r=+i;pxs.phase='play';pxs.revealed=false;pxs.finished=false;pxs.orders[+i]=pxShuffle(PX_PRIORITY[+i].tasks.length).map(k=>PX_PRIORITY[+i].tasks[k].id);ui.activitySaved=false;ui.lastSavedAttempt=null;pxRender();};
function pxPrMove(id,delta){const o=pxs.orders[pxs.r],i=o.indexOf(id),j=pxClamp(i+delta,0,o.length-1);if(i<0||i===j)return;pxPush();o.splice(j,0,o.splice(i,1)[0]);pxRender();requestAnimationFrame(()=>{const b=document.querySelector(`.px-task[data-arg0="${id}"] .px-move[data-arg1="${delta}"]:not(:disabled)`)||document.querySelector(`.px-task[data-arg0="${id}"] .px-move:not(:disabled)`);b?.focus({preventScroll:true});});}
PX_ACTIONS['px-pr-move']=([id,d])=>{if(!pxs||pxs.kind!=='priority'||pxs.phase!=='play'||pxs.revealed)return;pxPrMove(id,+d>0?1:-1);};
PX_ACTIONS['px-pr-drag']=(a,e)=>{if(!pxs||pxs.revealed||!e.dataTransfer)return;e.dataTransfer.setData('text/plain','carecraft-pr:'+a[0]);e.dataTransfer.effectAllowed='move';};
PX_ACTIONS['px-pr-over']=(a,e,el)=>{if(!pxs||pxs.revealed)return;e.preventDefault();el.classList.add('over');};
PX_ACTIONS['px-pr-drop']=(a,e,el)=>{e.preventDefault();el.classList.remove('over');const t=e.dataTransfer?.getData('text/plain')||'';if(!t.startsWith('carecraft-pr:')||!pxs||pxs.revealed||pxs.phase!=='play')return;const from=t.slice(13),o=pxs.orders[pxs.r],i=o.indexOf(from),j=o.indexOf(a[0]);if(i<0||j<0||i===j)return;pxPush();o.splice(j,0,o.splice(i,1)[0]);pxRender();};
PX_ACTIONS['px-pr-check']=()=>{if(!pxs||pxs.phase!=='play'||pxs.revealed)return;pxPush();const rd=PX_PRIORITY[pxs.r],R=pxPrScore(pxs.r);pxs.revealed=true;pxs.results[rd.id]={q:R.q,exact:R.exact,key:R.key};pxs.finished=false;pxRender();};
PX_ACTIONS['px-pr-note']=(a,e,el)=>{if(!pxs||pxs.kind!=='priority')return;pxs.notes[PX_PRIORITY[pxs.r].id]=(el?.value||'').slice(0,300);};
PX_ACTIONS['px-pr-next']=()=>{if(!pxs||!pxs.revealed)return;pxPush();const rd=PX_PRIORITY[pxs.r],R=pxs.results[rd.id];const all=PX_PRIORITY.every(r=>pxs.results[r.id]);
 pxRecord({id:pxs.id,kind:'priority',date:pxNow(),level:rd.level,mode:{round:rd.id},strong:R.q==='best'?1:0,ok:R.q==='ok'?1:0,risk:R.q==='risk'?1:0,total:1,secs:0,note:pxs.notes[rd.id]||''});
 const order=pxs.orders[pxs.r].map(id=>rd.tasks.find(t=>t.id===id).t);ui.activitySaved=false;logStudio(pxs.id,pxActivity(pxs.id).title+' · '+rd.title.replace(/^Round \d: /,''),`${R.exact} of ${rd.tasks.length} tasks in a reasonable place; ${R.key?'the key judgement came first':'the key judgement was not first'}.\n\nMy order:\n${order.map((t,i)=>(i+1)+'. '+t).join('\n')}${pxs.notes[rd.id]?'\n\nWhat would change my order: '+pxs.notes[rd.id]:''}\n\nOriginal fictional exercise. A learning record, not a measure of clinical competence.`);
 if(all){pxs.phase='result';pxs.finished=true;}else{pxs.phase='pick';pxs.revealed=false;}pxRender();};
PX_ACTIONS['px-pr-again']=()=>{if(!pxs||pxs.kind!=='priority')return;pxPush();pxs.phase='pick';pxs.finished=false;pxs.revealed=false;pxRender();};

/* ---------- 9. Spot the hazard ---------- */
const PX_HZ_NEUTRAL={'h-spill':'Floor near the foot of the bed','h-bell':'Floor beside the bed head','h-cable':'Cable running to the pump','h-exit':'Area in front of the door','h-rub':'Wall dispenser by the door','h-sharps':'Wall-mounted sharps box','h-screen':'Computer on wheels','h-trolley':'Medicines trolley','d-rub':'Wall dispenser at the bed head','d-bin':'Bin beside the bed','d-jug':'Locker beside the bed'};
const PX_HZ_SECONDS=60;
function pxHzOpen(id){pxs={kind:'hazard',id,phase:'setup',timed:false,hints:true,view:'scene',flags:{},hintsUsed:0,hintCat:'',left:PX_HZ_SECONDS,started:0,finished:false,hist:[]};ui.activitySaved=false;ui.lastSavedAttempt=null;ui.history=[];ui.dirty=false;pxRender();}
function pxHzSanitize(x){if(!['setup','play','result'].includes(x.phase))return null;const ids=new Set(PX_HAZARDS.map(h=>h.id)),flags={};for(const k of Object.keys(x.flags||{}))if(ids.has(k)&&x.flags[k])flags[k]=true;return {kind:'hazard',id:x.id,phase:x.phase,timed:!!x.timed,hints:x.hints!==false,view:x.view==='list'?'list':'scene',flags,hintsUsed:Math.max(0,Math.min(20,+x.hintsUsed||0)),hintCat:PX_HAZARD_CATS[x.hintCat]?x.hintCat:'',left:pxClamp(Math.round(+x.left||PX_HZ_SECONDS),0,PX_HZ_SECONDS),started:Number.isFinite(x.started)?x.started:0,finished:x.phase==='result'&&!!x.finished,secs:+x.secs||0,hist:[]};}
function pxHzScene(){return `<svg class="px-hzsvg" viewBox="0 0 800 480" role="img" aria-label="Illustration of a hospital bay: a bed with a person in it, a bedside locker, a medicines trolley, a computer on wheels, wall fittings, a door and items on the floor." focusable="false">
 <rect class="sc-wall" width="800" height="300"/><rect class="sc-floor" y="300" width="800" height="180"/><path class="sc-line" d="M0 300H800"/>
 <rect class="sc-window" x="28" y="48" width="140" height="124" rx="6"/><path class="sc-line" d="M98 48v124M28 110h140"/>
 <rect class="sc-board" x="318" y="64" width="160" height="72" rx="4"/><path class="sc-line" d="M334 88h92M334 108h124M334 124h70"/>
 <rect class="sc-door" x="690" y="84" width="102" height="218" rx="4"/><circle class="sc-knob" cx="708" cy="200" r="5"/><rect class="sc-exit" x="706" y="54" width="70" height="22" rx="3"/><text x="741" y="70" text-anchor="middle" class="sc-exit-t">EXIT</text>
 <rect class="sc-locker" x="146" y="268" width="64" height="76" rx="4"/><path class="sc-line" d="M146 304h64"/><rect class="sc-jug" x="168" y="236" width="20" height="30" rx="5"/><rect class="sc-cup" x="192" y="250" width="12" height="16" rx="2"/>
 <rect class="sc-bedhead" x="222" y="214" width="14" height="132" rx="3"/><rect class="sc-matt" x="236" y="262" width="292" height="40" rx="10"/><rect class="sc-blanket" x="300" y="250" width="228" height="38" rx="14"/><ellipse class="sc-pillow" cx="272" cy="256" rx="32" ry="15"/><circle class="sc-head" cx="272" cy="244" r="16"/><rect class="sc-base" x="236" y="302" width="292" height="12"/><circle class="sc-wheel" cx="262" cy="348" r="11"/><circle class="sc-wheel" cx="502" cy="348" r="11"/><path class="sc-line" d="M262 314v22M502 314v22"/>
 <rect class="sc-dispenser" x="201" y="184" width="28" height="46" rx="6"/><rect class="sc-level-full" x="206" y="190" width="18" height="30" rx="3"/>
 <rect class="sc-sharps" x="480" y="146" width="40" height="46" rx="4"/><rect class="sc-sharps-lid" x="476" y="140" width="48" height="10" rx="3"/><path class="sc-needle" d="M490 140l-3-14M500 140v-16M510 140l4-13"/>
 <rect class="sc-dispenser" x="648" y="158" width="30" height="52" rx="6"/><rect class="sc-level-empty" x="653" y="164" width="20" height="34" rx="3"/><path class="sc-line" d="M657 182h12"/>
 <rect class="sc-screen" x="34" y="238" width="96" height="64" rx="5"/><path class="sc-list" d="M46 252h40M46 264h54M46 276h46M46 288h58"/><rect class="sc-pole" x="78" y="302" width="8" height="30"/><rect class="sc-cow" x="42" y="330" width="80" height="12" rx="4"/><circle class="sc-wheel" cx="54" cy="352" r="8"/><circle class="sc-wheel" cx="110" cy="352" r="8"/>
 <rect class="sc-trolley" x="566" y="248" width="94" height="98" rx="6"/><path class="sc-line" d="M566 280h94M566 312h94"/><circle class="sc-key" cx="624" cy="296" r="5"/><path class="sc-keystem" d="M624 301v12"/><circle class="sc-wheel" cx="582" cy="356" r="8"/><circle class="sc-wheel" cx="646" cy="356" r="8"/>
 <rect class="sc-socket" x="538" y="290" width="16" height="22" rx="3"/><path class="sc-cable" d="M546 312C552 372 596 350 600 398S690 424 714 410"/><rect class="sc-pump" x="708" y="396" width="30" height="28" rx="4"/>
 <ellipse class="sc-spill" cx="455" cy="434" rx="52" ry="15"/>
 <path class="sc-bellcord" d="M238 330C240 380 262 410 286 418"/><rect class="sc-bell" x="282" y="410" width="22" height="16" rx="5"/>
 <rect class="sc-bin" x="362" y="350" width="32" height="44" rx="4"/><rect class="sc-binlid" x="358" y="344" width="40" height="8" rx="3"/>
 <rect class="sc-box" x="696" y="352" width="46" height="42" rx="3"/><rect class="sc-box" x="746" y="356" width="40" height="38" rx="3"/><rect class="sc-box" x="716" y="316" width="52" height="38" rx="3"/>
</svg>`;}
function pxHzMarkers(result){const s=pxs;return PX_HAZARDS.map(h=>{const on=!!s.flags[h.id],x=(h.x/8).toFixed(2),y=(h.y/4.8).toFixed(2);if(result){const st=h.hazard?(on?'best':'risk'):(on?'risk':'ok'),glyph=h.hazard?(on?'✓':'!'):(on?'×':'–');return `<span class="px-mark q-${st}" style="left:${x}%;top:${y}%" aria-hidden="true">${glyph}</span>`;}
 return `<button type="button" class="px-hot${on?' is-on':''}" style="left:${x}%;top:${y}%;--rw:${(h.r*2/8).toFixed(1)}%" aria-pressed="${on}" aria-label="${esc(PX_HZ_NEUTRAL[h.id])}${on?' (flagged)':''}" data-action="px-hz-flag" data-arg0="${h.id}"><span class="px-hot-i" aria-hidden="true">${on?'⚑':''}</span></button>`;}).join('');}
function pxHzRender(){const s=pxs;let body;if(s.phase==='setup')body=pxHzSetup();else if(s.phase==='play')body=pxHzPlay();else body=pxHzResult();pxShowPx(s.id,body);requestAnimationFrame(()=>{const d=document.getElementById('modal'),t=s.phase==='result'?d.querySelector('.px-outcome'):s.phase==='setup'?d.querySelector('.px-setup h3'):null;if(t){t.tabIndex=-1;t.focus({preventScroll:true});}});if(s.phase==='play'&&s.timed)pxHzClock();else pxStopTimer();}
function pxHzSetup(){const s=pxs,group=(key,label,opts,cur)=>`<div class="px-pref" role="radiogroup" aria-label="${esc(label)}"><span class="px-pref-l">${esc(label)}</span><div class="px-seg">${opts.map(([v,t])=>`<button type="button" class="px-segbtn" role="radio" aria-checked="${String(cur)===String(v)}" data-action="px-hz-pref" data-arg0="${key}" data-arg1="${v}">${esc(t)}</button>`).join('')}</div></div>`;
 return `<div class="px-setup">${pxBriefHTML(s.id,{open:true,how:'Scan the illustrated bay. Flag what you think is a hazard. Eleven things can be flagged; some of them are fine. Then see what you found and what you missed.'})}<section class="px-card"><h3>Choose how to practise</h3>${group('timed','Timing',[[false,'Untimed: explore'],[true,`Challenge: ${PX_HZ_SECONDS} seconds`]],s.timed)}${group('hints','Support',[[true,'Hints available'],[false,'No hints']],s.hints)}<p class="field-hint">The scene and the list view hold the same items, so you can use whichever suits you. Nothing here is a patient; every item is illustrative.</p></section><div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-hz-begin">Start scanning →</button></div></div>`;}
function pxHzPlay(){const s=pxs,n=Object.keys(s.flags).length,list=PX_HAZARDS.map(h=>{const on=!!s.flags[h.id];return `<li><span>${esc(PX_HZ_NEUTRAL[h.id])}</span><button type="button" class="btn ${on?'':'secondary'} px-flagbtn" aria-pressed="${on}" data-action="px-hz-flag" data-arg0="${h.id}">${on?'Flagged as a hazard':'Flag as a hazard'}</button></li>`;}).join('');
 return `<div class="px-play px-hzplay"><div class="px-hzbar"><span class="px-chip" role="status">Flagged: <b>${n}</b></span>${s.timed?`<span class="px-clock${s.left<=10?' over':''}" id="pxClockWrap"><span class="px-clock-l">Time</span><span id="pxClock" role="timer" aria-live="off">${pxMins(s.left)}</span></span>`:''}<div class="px-seg px-viewseg" role="group" aria-label="View"><button type="button" class="px-segbtn" aria-pressed="${s.view==='scene'}" data-action="px-hz-view" data-arg0="scene">Scene</button><button type="button" class="px-segbtn" aria-pressed="${s.view==='list'}" data-action="px-hz-view" data-arg0="list">List</button></div></div>
 <h3 class="px-q">What looks unsafe?</h3><p class="field-hint">Tap anything you would act on. Tap again to take the flag off. Some items are fine.</p>
 ${s.view==='scene'?`<div class="px-hzwrap">${pxHzScene()}${pxHzMarkers(false)}</div>`:`<ul class="px-hzlist">${list}</ul>`}
 ${s.hints?`<div class="px-hint">${s.hintCat?`<p class="px-hint-t" role="note"><b>Hint.</b> At least one hazard is still unflagged in: ${esc(PX_HAZARD_CATS[s.hintCat])}.</p>`:''}<button type="button" class="btn secondary" data-action="px-hz-hint">${s.hintCat?'Another hint':'Give me a hint'}</button></div>`:''}
 <div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-hz-finish">${n?'Show what I found →':'I see nothing to flag. Show me →'}</button></div></div>`;}
function pxHzScore(){const s=pxs,hz=PX_HAZARDS.filter(h=>h.hazard),dc=PX_HAZARDS.filter(h=>!h.hazard),found=hz.filter(h=>s.flags[h.id]),missed=hz.filter(h=>!s.flags[h.id]),falseA=dc.filter(h=>s.flags[h.id]),ignored=dc.filter(h=>!s.flags[h.id]);return {hz,dc,found,missed,falseA,ignored};}
function pxHzResult(){const s=pxs,R=pxHzScore(),cats=Object.entries(PX_HAZARD_CATS).map(([k,name])=>{const tot=R.hz.filter(h=>h.cat===k).length,got=R.found.filter(h=>h.cat===k).length;return {k,name,tot,got};}).filter(c=>c.tot),q=R.missed.length===0&&!R.falseA.length?'strong':R.found.length>=6?'mixed':'weak';
 return `<div class="px-debrief"><section class="px-outcome px-outcome-${q}"><span class="eyebrow">YOUR SCAN</span><h3>${R.found.length} of ${R.hz.length} hazards found${R.falseA.length?`, ${R.falseA.length} false alarm${R.falseA.length>1?'s':''}`:''}</h3><p>${R.missed.length?'Some hazards slipped past. Notice which categories they are in: your attention tends to follow what you expect.':'You found every hazard.'} ${R.falseA.length?'A false alarm is not a failure: the skill is telling a real hazard from a look-alike.':''}</p></section>
 <section class="px-tiles"><div class="px-tile"><strong>${R.found.length} of ${R.hz.length}</strong><span>hazards found</span></div><div class="px-tile"><strong>${R.falseA.length}</strong><span>false alarms</span></div><div class="px-tile"><strong>${s.timed?pxMins(PX_HZ_SECONDS-s.left):'—'}</strong><span>${s.timed?'time used':'untimed'}</span></div><div class="px-tile"><strong>${s.hintsUsed}</strong><span>hints used</span></div></section>
 <section class="px-sec"><h3>The scene, marked</h3><div class="px-hzwrap">${pxHzScene()}${pxHzMarkers(true)}</div><p class="px-legend-line"><span><b class="px-mk q-best">✓</b> Found</span><span><b class="px-mk q-risk">!</b> Missed</span><span><b class="px-mk q-risk">×</b> False alarm</span><span><b class="px-mk q-ok">–</b> Fine, correctly left alone</span></p></section>
 <section class="px-sec"><h3>By category</h3><ul class="px-bars-chart" aria-label="Hazards found by category">${cats.map(c=>`<li><span class="px-bc-l">${esc(c.name)}</span><span class="px-bc-bar" role="img" aria-label="${c.got} of ${c.tot} found"><i style="width:${pxPct(c.got,c.tot)}%"></i></span><span class="px-bc-n">${c.got}/${c.tot}</span></li>`).join('')}</ul></section>
 <section class="px-sec"><h3>Every item explained</h3><ul class="px-verdicts">${PX_HAZARDS.map(h=>{const on=!!s.flags[h.id],st=h.hazard?(on?'best':'risk'):(on?'risk':'ok');return `<li class="q-${st}"><b>${esc(h.label)}</b> ${pxQTag(st).replace(PX_Q[st][0],h.hazard?(on?'Found':'Missed'):(on?'False alarm':'Fine'))}<p class="px-cmp-why">${esc(h.why)}</p></li>`;}).join('')}</ul></section>
 <section class="px-sec px-take"><h3>Take-aways</h3>${pxList(['Scan in a pattern: floor and walkways, then walls and fittings, then equipment, then people and information.','Fix what you can safely fix, report what you cannot, and put up a sign while you wait.','Look-alikes are normal: a full dispenser, a closed bin or a drink within reach are good practice. Telling them apart is part of the skill.','Hazards cluster in categories. If you missed one, ask why your attention skipped that category.'])}</section>
 <p class="px-saved" role="status">${icon('check')}Saved to My Growth.</p><div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-hz-again">Scan again →</button></div></div>`;}
function pxHzClock(){pxStopTimer();const s=pxs;const tick=()=>{if(!pxs||pxs!==s||s.phase!=='play'||!s.timed)return pxStopTimer();const el=document.getElementById('pxClock');if(el)el.textContent=pxMins(s.left);document.getElementById('pxClockWrap')?.classList.toggle('over',s.left<=10);if(s.left<=0){pxStopTimer();toast('Time is up. Here is what you found.');PX_ACTIONS['px-hz-finish']();return;}s.left--;};tick();pxTimer=setInterval(tick,1000);}
PX_ENGINES.hazard={open:pxHzOpen,render:pxHzRender,sanitize:pxHzSanitize};
PX_ACTIONS['px-hz-pref']=([k,v])=>{if(!pxs||pxs.kind!=='hazard'||pxs.phase!=='setup')return;if(k==='timed'||k==='hints'){pxs[k]=v==='true';pxRender();}};
PX_ACTIONS['px-hz-begin']=()=>{if(!pxs||pxs.phase!=='setup')return;pxPush();pxs.phase='play';pxs.left=PX_HZ_SECONDS;pxs.started=Date.now();pxRender();};
PX_ACTIONS['px-hz-view']=([v])=>{if(!pxs||pxs.phase!=='play')return;pxs.view=v==='list'?'list':'scene';pxRender();requestAnimationFrame(()=>document.querySelector(`.px-viewseg [data-arg0="${pxs.view}"]`)?.focus({preventScroll:true}));};
PX_ACTIONS['px-hz-flag']=([id])=>{if(!pxs||pxs.phase!=='play'||!PX_HAZARDS.some(h=>h.id===id))return;pxPush();if(pxs.flags[id])delete pxs.flags[id];else pxs.flags[id]=true;pxRender();requestAnimationFrame(()=>document.querySelector(`[data-action="px-hz-flag"][data-arg0="${id}"]`)?.focus({preventScroll:true}));};
PX_ACTIONS['px-hz-hint']=()=>{if(!pxs||pxs.phase!=='play'||!pxs.hints)return;const R=pxHzScore(),cats=[...new Set(R.missed.map(h=>h.cat))];if(!cats.length){toast('You have flagged every hazard. Check your false alarms, then finish.');return;}pxPush();pxs.hintsUsed++;const others=cats.filter(c=>c!==pxs.hintCat);pxs.hintCat=(others.length?others:cats)[0];pxRender();};
PX_ACTIONS['px-hz-finish']=()=>{if(!pxs||pxs.kind!=='hazard'||pxs.phase!=='play')return;pxStopTimer();pxPush();const R=pxHzScore();pxs.phase='result';pxs.finished=true;pxs.secs=Math.round((Date.now()-(pxs.started||Date.now()))/1000);const good=R.found.length+R.ignored.length,total=PX_HAZARDS.length;
 pxRecord({id:pxs.id,kind:'hazard',date:pxNow(),level:'foundation',mode:{timed:pxs.timed,hints:pxs.hints},strong:good,ok:0,risk:total-good,total,over:0,hints:pxs.hintsUsed,secs:pxs.secs,found:R.found.length,falseAlarms:R.falseA.length});
 ui.activitySaved=false;logStudio(pxs.id,pxActivity(pxs.id).title,`${R.found.length} of ${R.hz.length} hazards found; ${R.falseA.length} false alarm${R.falseA.length===1?'':'s'}. ${pxs.timed?'Timed challenge.':'Untimed.'}\nMissed: ${R.missed.map(h=>h.label).join('; ')||'none'}.\n\nOriginal fictional exercise. A learning record, not a measure of clinical competence.`);pxRender();};
PX_ACTIONS['px-hz-again']=()=>{if(!pxs||pxs.kind!=='hazard')return;const keep={timed:pxs.timed,hints:pxs.hints};pxHzOpen(pxs.id);Object.assign(pxs,keep);pxRender();};

/* ---------- 10. Incident replay: timeline, defences and a fair response ---------- */
function pxInOpen(id){pxs={kind:'incident',id,phase:'replay',ev:0,flags:{},flagsDone:false,resp:{},finished:false,hist:[]};ui.activitySaved=false;ui.lastSavedAttempt=null;ui.history=[];ui.dirty=false;pxRender();}
function pxInSanitize(x){if(!['replay','flag','fair','result'].includes(x.phase)||!Number.isInteger(x.ev)||x.ev<0||x.ev>=PX_INCIDENT.events.length)return null;const ev=new Set(PX_INCIDENT.events.map(e=>e.id)),flags={};for(const k of Object.keys(x.flags||{}))if(ev.has(k)&&x.flags[k])flags[k]=true;const resp={};for(const b of PX_INCIDENT.behaviours)if(['error','risk','reckless'].includes(x.resp?.[b.id]))resp[b.id]=x.resp[b.id];return {kind:'incident',id:x.id,phase:x.phase,ev:x.ev,flags,flagsDone:!!x.flagsDone,resp,finished:x.phase==='result'&&!!x.finished,hist:[]};}
function pxInRender(){const s=pxs;let body;if(s.phase==='replay')body=pxInReplay();else if(s.phase==='flag')body=pxInFlag();else if(s.phase==='fair')body=pxInFair();else body=pxInResult();pxShowPx(s.id,body);requestAnimationFrame(()=>{const d=document.getElementById('modal'),t=s.phase==='result'?d.querySelector('.px-outcome'):s.phase==='replay'?d.querySelector('.px-ev.now'):s.phase==='flag'&&s.flagsDone?d.querySelector('.px-feedback'):d.querySelector('.px-q');if(t){t.tabIndex=-1;t.focus({preventScroll:false});}});}
function pxInTimeline(upTo,flags,reveal){const E=PX_INCIDENT.events,n=E.length;let svg=`<svg class="px-tlsvg" viewBox="0 0 ${n*90} 70" aria-hidden="true" focusable="false"><path class="px-route" d="M45 30H${n*90-45}"/>`;E.forEach((e,i)=>{const cx=45+i*90,on=i<=upTo,cur=i===upTo,hole=reveal&&PX_INCIDENT.flagCorrect.includes(e.id),flag=flags&&flags[e.id];svg+=`<g transform="translate(${cx} 30)" class="px-tln${on?' on':''}${cur?' cur':''}${hole?' hole':''}${flag?' flag':''}"><circle r="${cur?14:11}"/>${hole?'<path d="M-5 -5l10 10M5 -5l-10 10" fill="none" stroke-width="2.4" stroke-linecap="round"/>':''}</g><text x="${cx}" y="64" text-anchor="middle" class="px-nlabel">${e.time}</text>`;});return svg+'</svg>';}
function pxInReplay(){const s=pxs,E=PX_INCIDENT.events,last=s.ev>=E.length-1;
 return `<div class="px-play px-incplay"><p class="px-lead">${esc(PX_INCIDENT.intro)}</p><div class="px-pathscroll">${pxInTimeline(s.ev)}</div><div class="px-progress"><span>Event ${s.ev+1} of ${E.length}</span><label class="px-slider" for="pxInSlide"><span class="px-sr">Step through the timeline</span><input id="pxInSlide" type="range" min="0" max="${E.length-1}" value="${s.ev}" data-oninput="px-in-slide"></label></div><ol class="px-evlist">${E.slice(0,s.ev+1).map((e,i)=>`<li class="px-ev${i===s.ev?' now':''}" ${i===s.ev?'aria-current="step"':''}><time>${e.time}</time><p>${esc(e.t)}</p></li>`).join('')}</ol>
 <div class="modal-actions"><button type="button" class="btn secondary" data-action="px-in-prev" ${s.ev===0?'disabled':''}>← Earlier event</button><button type="button" class="btn" data-px-next data-action="px-in-next">${last?'Where could it have been caught?':'Next event'} →</button></div></div>`;}
function pxInFlag(){const s=pxs,E=PX_INCIDENT.events,correct=PX_INCIDENT.flagCorrect;let fb='';if(s.flagsDone){const hits=correct.filter(id=>s.flags[id]),missed=correct.filter(id=>!s.flags[id]),falseF=Object.keys(s.flags).filter(id=>!correct.includes(id));fb=`<section class="px-feedback q-${missed.length===0&&!falseF.length?'best':missed.length<=1?'ok':'risk'}" aria-live="polite"><div class="px-fb-head">${pxQGlyph(missed.length===0&&!falseF.length?'best':missed.length<=1?'ok':'risk',30)}<div><strong>${hits.length} of ${correct.length} openings found${falseF.length?`, ${falseF.length} flagged where nothing was missed`:''}</strong></div></div><ul class="px-verdicts">${E.map(e=>{const should=correct.includes(e.id),on=!!s.flags[e.id],q=should?(on?'best':'risk'):(on?'ok':null);return q||should?`<li class="q-${q||'ok'}"><b>${e.time}</b> ${should?`<span class="px-chip">Layer: ${esc(e.layer)}</span>`:''}<p>${esc(e.note)}</p></li>`:'';}).join('')}</ul></section><div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-in-fair">Respond fairly →</button></div>`;}
 return `<div class="px-play"><h3 class="px-q">Where could this have been caught?</h3><p class="field-hint">Flag every event where something could have prevented, caught or softened what followed. Not every event is a gap, and a good response is not a gap either.</p><div class="px-pathscroll">${pxInTimeline(E.length-1,s.flags,s.flagsDone)}</div><ul class="px-flaglist">${E.map(e=>{const on=!!s.flags[e.id];return `<li><button type="button" class="px-flagrow${on?' is-on':''}" aria-pressed="${on}" ${s.flagsDone?'disabled':''} data-action="px-in-flag" data-arg0="${e.id}"><time>${e.time}</time><span>${esc(e.t)}</span><b aria-hidden="true">${on?'⚑':''}</b></button></li>`;}).join('')}</ul>${s.flagsDone?'':`<div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-in-check">Check my flags →</button></div>`}${fb}</div>`;}
function pxInFair(){const s=pxs,B=PX_INCIDENT.behaviours,done=B.every(b=>s.resp[b.id]);
 return `<div class="px-play"><h3 class="px-q">What is a fair response to each behaviour?</h3><p class="field-hint">Just Culture separates human error (console and look at the system), at-risk behaviour (coach and make the right way easy) and reckless behaviour (a formal process). Your organisation’s own process decides in real life.</p><ul class="px-behaviours">${B.map(b=>{const r=s.resp[b.id],ans=!!r,ok=r===b.best;return `<li class="px-beh${ans?(ok?' q-best':' q-ok'):''}"><p>${esc(b.t)}</p><div class="px-seg" role="group" aria-label="Response to: ${esc(b.t)}">${Object.entries(PX_INCIDENT.responses).map(([k,[n,sub]])=>`<button type="button" class="px-segbtn" aria-pressed="${r===k}" ${ans?'disabled':''} data-action="px-in-resp" data-arg0="${b.id}" data-arg1="${k}">${esc(n)}<small>${esc(sub)}</small></button>`).join('')}</div>${ans?`<div class="px-feedback q-${ok?'best':'ok'}" aria-live="polite">${pxQTag(ok?'best':'ok').replace(PX_Q[ok?'best':'ok'][0],ok?'Fair response':'Look again')}<p>${ok?'':`<b>Most fitting: ${esc(PX_INCIDENT.responses[b.best][0])}.</b> `}${esc(b.why)}</p></div>`:''}</li>`;}).join('')}</ul>${done?`<div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-in-finish">See the debrief →</button></div>`:''}</div>`;}
function pxCheese(){const L=[...new Set(PX_INCIDENT.events.filter(e=>e.layer).map(e=>e.layer))],n=L.length,W=120*n+60;let svg=`<svg class="px-cheese" viewBox="0 0 ${W} 230" aria-hidden="true" focusable="false">`;L.forEach((l,i)=>{const x=50+i*120,holes=[[x+10,70,9],[x+26,170,7],[x-8,150,10],[x+4,120,15]];svg+=`<g class="px-slice"><path d="M${x} 24l56 -10v186l-56 10z"/>${holes.map(([cx,cy,r])=>`<ellipse cx="${cx+14}" cy="${cy}" rx="${r}" ry="${r*1.2}" class="px-hole${cy===120?' align':''}"/>`).join('')}<circle cx="${x+28}" cy="${12}" r="12" class="px-sn"/><text x="${x+28}" y="17" text-anchor="middle" class="px-snt">${i+1}</text></g>`;});svg+=`<path class="px-arrow" d="M8 120H${W-26}"/><path class="px-arrowhead" d="M${W-30} 108l22 12-22 12z"/></svg>`;return `<figure class="px-cheesefig"><div class="px-pathscroll">${svg}</div><ol class="px-cheeselist">${L.map(l=>`<li><b>${esc(l)}</b><span>${esc(PX_INCIDENT.events.find(e=>e.layer===l).note)}</span></li>`).join('')}</ol><figcaption class="px-legend"><span>Each slice is a defence. A hole is a weakness. Harm needs the holes to line up.</span></figcaption></figure>`;}
function pxInResult(){const s=pxs,hits=PX_INCIDENT.flagCorrect.filter(id=>s.flags[id]).length,falseF=Object.keys(s.flags).filter(id=>!PX_INCIDENT.flagCorrect.includes(id)).length,fair=PX_INCIDENT.behaviours.filter(b=>s.resp[b.id]===b.best).length,q=hits>=3&&fair>=3?'strong':hits>=2||fair>=2?'mixed':'weak';
 return `<div class="px-debrief"><section class="px-outcome px-outcome-${q}"><span class="eyebrow">YOUR REPLAY</span><h3>${hits} of ${PX_INCIDENT.flagCorrect.length} openings found, ${fair} of ${PX_INCIDENT.behaviours.length} fair responses</h3><p>No single person caused this. Four defences each had a gap and the gaps lined up. The useful questions are how the gaps formed and how to close them.</p></section><section class="px-sec"><h3>The defences and their holes</h3>${pxCheese()}</section><section class="px-sec"><h3>The timeline, marked</h3><div class="px-pathscroll">${pxInTimeline(PX_INCIDENT.events.length-1,s.flags,true)}</div><p class="px-legend-line"><span><b class="px-mk q-risk">✕</b> A gap in a defence</span><span><b class="px-mk q-ok">⚑</b> You flagged it</span></p></section>
 <section class="px-sec"><h3>Fair responses</h3><ul class="px-verdicts">${PX_INCIDENT.behaviours.map(b=>`<li class="q-${s.resp[b.id]===b.best?'best':'ok'}"><b>${esc(PX_INCIDENT.responses[b.best][0])}</b><p>${esc(b.t)}</p><p class="px-cmp-why">${esc(b.why)}</p></li>`).join('')}</ul></section>
 <section class="px-sec px-take"><h3>Take-aways</h3>${pxList(['Incidents are usually several small gaps that line up, not one person’s mistake.','Look for what made each gap likely: an interruption with no overdue marker, a handover with no prompt, a habit that became the default.','A fair response matches the behaviour: console and redesign for error, coach for at-risk shortcuts, a formal process for reckless acts.','After an event, ask what made it possible, and then what will make the right thing the easy thing.'])}</section><p class="px-saved" role="status">${icon('check')}Saved to My Growth.</p><div class="modal-actions"><button type="button" class="btn" data-px-next data-action="px-in-again">Replay again →</button></div></div>`;}
PX_ENGINES.incident={open:pxInOpen,render:pxInRender,sanitize:pxInSanitize};
PX_ACTIONS['px-in-next']=()=>{if(!pxs||pxs.phase!=='replay')return;pxPush();if(pxs.ev>=PX_INCIDENT.events.length-1)pxs.phase='flag';else pxs.ev++;pxRender();};
PX_ACTIONS['px-in-prev']=()=>{if(!pxs||pxs.phase!=='replay'||pxs.ev<=0)return;pxs.ev--;pxRender();};
PX_ACTIONS['px-in-slide']=(a,e,el)=>{if(!pxs||pxs.phase!=='replay')return;const v=pxClamp(+el.value||0,0,PX_INCIDENT.events.length-1);if(v===pxs.ev)return;pxs.ev=v;pxRender();requestAnimationFrame(()=>document.getElementById('pxInSlide')?.focus({preventScroll:true}));};
PX_ACTIONS['px-in-flag']=([id])=>{if(!pxs||pxs.phase!=='flag'||pxs.flagsDone||!PX_INCIDENT.events.some(e=>e.id===id))return;pxPush();if(pxs.flags[id])delete pxs.flags[id];else pxs.flags[id]=true;pxRender();requestAnimationFrame(()=>document.querySelector(`[data-action="px-in-flag"][data-arg0="${id}"]`)?.focus({preventScroll:true}));};
PX_ACTIONS['px-in-check']=()=>{if(!pxs||pxs.phase!=='flag'||pxs.flagsDone)return;pxPush();pxs.flagsDone=true;pxRender();};
PX_ACTIONS['px-in-fair']=()=>{if(!pxs||!pxs.flagsDone)return;pxPush();pxs.phase='fair';pxRender();};
PX_ACTIONS['px-in-resp']=([id,k])=>{if(!pxs||pxs.phase!=='fair'||pxs.resp[id]||!['error','risk','reckless'].includes(k)||!PX_INCIDENT.behaviours.some(b=>b.id===id))return;pxPush();pxs.resp[id]=k;pxRender();requestAnimationFrame(()=>document.querySelector('.px-beh .px-feedback')?.closest('li')?.scrollIntoView({block:'nearest'}));};
PX_ACTIONS['px-in-finish']=()=>{if(!pxs||pxs.phase!=='fair'||!PX_INCIDENT.behaviours.every(b=>pxs.resp[b.id]))return;pxPush();const hits=PX_INCIDENT.flagCorrect.filter(id=>pxs.flags[id]).length,falseF=Object.keys(pxs.flags).filter(id=>!PX_INCIDENT.flagCorrect.includes(id)).length,fair=PX_INCIDENT.behaviours.filter(b=>pxs.resp[b.id]===b.best).length,total=PX_INCIDENT.flagCorrect.length+PX_INCIDENT.behaviours.length,strong=Math.max(0,hits-falseF)+fair;pxs.phase='result';pxs.finished=true;
 pxRecord({id:pxs.id,kind:'incident',date:pxNow(),level:'advanced',mode:{},strong,ok:0,risk:total-strong,total,secs:0});ui.activitySaved=false;logStudio(pxs.id,pxActivity(pxs.id).title,`${hits} of ${PX_INCIDENT.flagCorrect.length} openings found; ${fair} of ${PX_INCIDENT.behaviours.length} fair responses.\n\n`+PX_INCIDENT.behaviours.map(b=>`${b.t}\nChose: ${PX_INCIDENT.responses[pxs.resp[b.id]][0]}; most fitting: ${PX_INCIDENT.responses[b.best][0]}.`).join('\n\n')+'\n\nOriginal fictional exercise. A learning record, not a measure of clinical competence.');pxRender();};
PX_ACTIONS['px-in-again']=()=>{if(!pxs||pxs.kind!=='incident')return;pxInOpen(pxs.id);};

/* ---------- 11. Retrieval drill (spaced revisits of decisions) ---------- */
let pxd=null;
function pxCardResolve(key){const [k,id,node]=key.split(':');if(k!=='s')return null;const sc=PX_SCENARIOS[id],n=sc&&sc.nodes[node];if(!n)return null;return {title:pxActivity(id)?.title||id,scene:n.scene,q:n.q,opts:n.opts,nodeTitle:n.title};}
function pxDrillStart(){const due=pxDueCards().slice(0,5);if(!due.length){toast('Nothing due. Practice a scenario to build your drill.');return;}pxd={queue:due.map(c=>c.key),i:0,sel:null,ok:0,order:{}};ui.activity=null;pxDrillRender();}
function pxDrillRender(){const d=pxd,key=d.queue[d.i];if(d.i>=d.queue.length){showModal('Retrieval drill done',`${d.ok} of ${d.queue.length} chosen strongly`,`<div class="px-debrief"><section class="px-outcome px-outcome-${d.ok===d.queue.length?'strong':'mixed'}"><span class="eyebrow">SPACED RETRIEVAL</span><h3>${d.ok} of ${d.queue.length} decisions chosen strongly</h3><p>Decisions you got right move to a longer gap (1, 3, 7, 14, then 30 days). Others return tomorrow. A learning aid, not an assessment.</p></section><div class="modal-actions"><button type="button" class="btn" data-action="close">Back to Practice</button></div></div>`);document.getElementById('modal').classList.add('px-modal');return;}
 const c=pxCardResolve(key),order=d.order[key]||(d.order[key]=pxShuffle(c.opts.length)),done=d.sel!==null;
 showModal('Retrieval drill',`Decision ${d.i+1} of ${d.queue.length} · ${esc(c.title)}`,`<div class="px-play"><article class="px-scene"><h3 class="px-scene-t">${esc(c.nodeTitle)}</h3><p>${esc(c.scene)}</p></article><h3 class="px-q" tabindex="-1">${esc(c.q)}</h3><div class="px-opts answer-list" role="group" aria-label="Options">${order.map((oi,di)=>{const o=c.opts[oi],sel=d.sel===di;return `<button type="button" class="answer px-opt ${done?(o.q==='best'?'correct':sel?'incorrect':''):''}" ${done?'disabled':''} data-action="px-drill-pick" data-arg0="${di}"><span class="letter">${'ABCD'[di]}</span><span class="px-opt-t">${esc(o.t)}</span>${done?`<span class="px-opt-q q-${o.q}">${pxQGlyph(o.q,18)}<span class="px-sr">${PX_Q[o.q][0]}</span></span>`:''}</button>`;}).join('')}</div>${done?`<section class="px-feedback q-${c.opts[order[d.sel]].q}" aria-live="polite"><div class="px-fb-head">${pxQGlyph(c.opts[order[d.sel]].q,30)}<strong>${PX_Q[c.opts[order[d.sel]].q][0]}</strong></div><p>${esc(c.opts[order[d.sel]].why)}</p></section><div class="modal-actions"><button type="button" class="btn" data-action="px-drill-next">${d.i===d.queue.length-1?'Finish':'Next decision'} →</button></div>`:''}</div>`);
 document.getElementById('modal').classList.add('px-modal');requestAnimationFrame(()=>{const t=document.querySelector(done?'.px-feedback':'.px-q');if(t){t.tabIndex=-1;t.focus();}});}
PX_ACTIONS['px-drill']=()=>pxDrillStart();
PX_ACTIONS['px-drill-pick']=([i])=>{if(!pxd||pxd.sel!==null)return;const key=pxd.queue[pxd.i],c=pxCardResolve(key),order=pxd.order[key];if(!c||!order[+i]&&order[+i]!==0)return;pxd.sel=+i;const o=c.opts[order[+i]],card=pxStore().cards[key];if(card){if(o.q==='best'){card.box=Math.min(5,(card.box||0)+1);card.due=laterDay([1,3,7,14,30][card.box-1]);pxd.ok++;}else{card.box=0;card.due=laterDay(1);}pxStore().drilled++;persist();}pxDrillRender();};
PX_ACTIONS['px-drill-next']=()=>{if(!pxd||pxd.sel===null)return;pxd.i++;pxd.sel=null;pxDrillRender();};

/* ---------- 12. Practice hub ---------- */
function pxRadar(cov){const R=96,cx=160,cy=150,n=cov.length,pt=(i,v)=>{const a=-Math.PI/2+i*2*Math.PI/n;return [cx+Math.cos(a)*R*v,cy+Math.sin(a)*R*v];};
 let svg=`<svg class="px-radar" viewBox="0 0 320 300" role="img" aria-label="Practice coverage by skill: ${cov.map(c=>c.skill.short+' '+c.done+' of '+c.total).join(', ')}">`;
 for(const k of [1/3,2/3,1])svg+=`<polygon class="px-rgrid" points="${cov.map((_,i)=>pt(i,k).join(',')).join(' ')}"/>`;
 cov.forEach((c,i)=>{const [x,y]=pt(i,1),[lx,ly]=pt(i,1.2);svg+=`<line class="px-rgrid" x1="${cx}" y1="${cy}" x2="${x}" y2="${y}"/><text class="px-rlab" x="${lx}" y="${ly+4}" text-anchor="${lx<cx-8?'end':lx>cx+8?'start':'middle'}">${esc(c.skill.short)}</text>`;});
 svg+=`<polygon class="px-rarea" points="${cov.map((c,i)=>pt(i,Math.max(.04,c.value)).join(',')).join(' ')}"/>`+cov.map((c,i)=>{const [x,y]=pt(i,Math.max(.04,c.value));return `<circle class="px-rdot" cx="${x}" cy="${y}" r="4"/>`;}).join('')+'</svg>';return svg;}
function pxFilteredActivities(){const f=ui.practice;return HCA_ACTIVITIES.filter(a=>PX_META[a.id]&&(f.format==='all'||a.type===f.format)&&(f.duration==='all'||activityMinutes(a)<=+f.duration)&&(!f.level||f.level==='all'||PX_META[a.id].level===f.level)&&(!f.skill||f.skill==='all'||PX_META[a.id].skill===f.skill||(PX_META[a.id].also||[]).includes(f.skill))&&(f.mode==='all'||(f.mode==='team'?a.type==='team':a.type!=='team'))&&(f.topic==='all'||(a.title+' '+a.desc).toLowerCase().includes(f.topic)));}
function pxCard(a){const m=PX_META[a.id],done=pxDone(a.id),best=pxBestOf(a.id),type=({scenarios:'Scenario',studios:'Interactive studio',simulations:'3D simulation',team:'Team practice'})[a.type];
 return `<article class="card activity-card px-card-a" data-activity-id="${a.id}" data-action="activity" data-arg0="${a.id}" role="link" tabindex="0" aria-label="${esc(a.title)}. ${pxLevel(m.level).name}, about ${m.min} minutes${done?', tried':''}"><div class="px-card-top">${pxSkillChip(m.skill)}${pxLevelBadge(m.level)}</div><div class="card-copy"><h3>${esc(a.title)}</h3><p>${esc(a.desc)}</p><p class="px-practise"><b>Practise:</b> ${esc(m.practise.slice(0,2).join(' · '))}</p><div class="card-meta"><span>${type}</span><span>${m.min} min</span><span>${esc(m.units)}</span></div><div class="card-status px-status${done?' done':''}">${done?(best?`✓ Tried · best ${best.strong} of ${best.total}`:'✓ Tried'):'Not tried yet'} <span aria-hidden="true">→</span></div></div><div class="card-controls">${btn('ⓘ','guide',[a.id],'icon-button',`aria-label="Activity guide: ${esc(a.title)}"`)}</div></article>`;}
function pxChips(key,opts,cur){return `<div class="px-chiprow" role="group" aria-label="${key==='level'?'Level':'Skill'}">${opts.map(([v,t])=>`<button type="button" class="px-fchip" aria-pressed="${(cur||'all')===v}" data-action="px-filter" data-arg0="${key}" data-arg1="${v}">${esc(t)}</button>`).join('')}</div>`;}
renderPractice=function(){const f=ui.practice,items=pxFilteredActivities(),rec=pxRecommend(),cov=pxCoverage(),due=pxDueCards().length,rv=hcaDue().length,tried=HCA_ACTIVITIES.filter(a=>pxDone(a.id)).length,days=pxDays(),set=new Set(pxActivityDays()),cal=pxCalibration(),group=f.group||'level';
 const recCard=`<section class="px-hero" aria-labelledby="pxRecT"><span class="eyebrow">RECOMMENDED NEXT</span><h2 id="pxRecT">${esc(rec.title)}</h2><p>${esc(rec.why)}</p>${rec.kind==='activity'?`<div class="px-brief-chips">${pxLevelBadge(PX_META[rec.id].level)}${pxSkillChip(PX_META[rec.id].skill)}<span class="px-chip">${icon('clock')}About ${PX_META[rec.id].min} min</span></div>`:''}${rec.kind==='resume'?btn(rec.cta,'resume',[],'primary'):rec.kind==='drill'?btn(rec.cta,'px-drill',[],'primary'):btn(rec.cta,'activity',[rec.id],'primary')}</section>`;
 const strip=`<section class="px-due" aria-label="Due for review"><div>${icon('calendar')}<span><b>${due}</b> decision${due===1?'':'s'} to revisit</span>${btn('Retrieval drill','px-drill',[],'secondary',due?'':'disabled')}</div><div>${icon('book')}<span><b>${rv}</b> Smart Review prompt${rv===1?'':'s'} due</span>${btn('Start review','review',[],'secondary',rv?'':'disabled')}</div></section>`;
 const stats=`<section class="px-stats" aria-label="Your progress"><div class="px-tiles"><div class="px-tile"><strong>${tried}</strong><span>of ${HCA_ACTIVITIES.length} activities tried</span></div><div class="px-tile"><strong>${pxStreak()}</strong><span>day streak</span></div><div class="px-tile"><strong>${cal.n?pxPct(cal.match,cal.n)+'%':'—'}</strong><span>confidence matched outcome</span></div></div><div class="week-strip px-week" aria-label="Practice in the last seven days">${days.map(d=>{const n=[...set].filter(x=>x===d).length||0,c=pxActivityDays().filter(x=>x===d).length;return `<div class="${c?'has-activity':''}" title="${c} activities"><span>${new Date(d+'T12:00').toLocaleDateString('en-GB',{weekday:'short'})}</span><i>${c||'·'}</i></div>`;}).join('')}</div></section>`;
 const radar=`<section class="px-radarcard" aria-labelledby="pxRadT"><h2 id="pxRadT">Practice coverage</h2><div class="px-radarwrap">${pxRadar(cov)}<ul class="px-skilllist">${cov.map(c=>`<li><span>${pxSkillChip(c.skill.id)}</span><span class="px-sk-n">${c.done} of ${c.total}</span><span class="px-sk-l">${c.reached?pxLevel(['','foundation','core','advanced'][c.reached]).name+' reached':'Not started'}</span></li>`).join('')}</ul></div><p class="field-hint">Coverage shows which skills you have rehearsed, not how competent you are.</p></section>`;
 let groups;const render=arr=>`<div class="card-grid px-grid">${arr.map(pxCard).join('')}</div>`;
 if(group==='skill')groups=PX_SKILLS.map(s=>({t:s.name,d:s.blurb,a:items.filter(a=>PX_META[a.id].skill===s.id)}));else groups=PX_LEVELS.map(l=>({t:l.name,d:l.blurb,a:items.filter(a=>PX_META[a.id].level===l.id)}));
 groups=groups.filter(g=>g.a.length);
 const recent=[...state.studioAttempts].sort((a,b)=>Date.parse(b.date)-Date.parse(a.date)).slice(0,4);
 return `${header('Practice','Rehearse real conversations, decisions and handovers in fictional scenarios, with consequences, feedback and a debrief.')}<div class="px-top">${recCard}${radar}${stats}</div>${strip}<section class="px-browse" aria-label="Browse activities"><div class="px-filters"><div><span class="px-pref-l">Level</span>${pxChips('level',[['all','All levels'],...PX_LEVELS.map(l=>[l.id,l.name])],f.level)}</div><div><span class="px-pref-l">Skill</span>${pxChips('skill',[['all','All skills'],...PX_SKILLS.map(s=>[s.id,s.short])],f.skill)}</div></div><div class="filter-bar">${filterSelect('format','Format',[['all','All formats'],['scenarios','Scenario'],['studios','Interactive studio'],['simulations','3D simulation'],['team','Team practice']],f.format,'practice-filter')}${filterSelect('duration','Duration',[['all','Any length'],['5','5 min or less'],['7','7 min or less']],f.duration,'practice-filter')}<label>Group by<select data-field="px-group"><option value="level"${group==='level'?' selected':''}>Level</option><option value="skill"${group==='skill'?' selected':''}>Skill</option></select></label></div><div class="result-count">${items.length} activities · ${disclosure()}</div>${groups.length?groups.map(g=>`<section class="px-group"><h2>${esc(g.t)}</h2><p class="field-hint">${esc(g.d)}</p>${render(g.a)}</section>`).join(''):empty('Try another combination.','Change a filter to find a different practice.','practice','Reset practice filters')}</section>${recent.length?`<section class="px-recent"><div class="section-title"><h2>Recent attempts</h2>${btn('All in My Growth','navigate',['progress'],'ghost')}</div><ul>${recent.map(r=>`<li><b>${esc(r.label)}</b><small>${new Date(r.date).toLocaleDateString('en-GB')}</small></li>`).join('')}</ul></section>`:''}<p class="footnote">These original educational exercises are fictional. They are not clinical certification, CPD credit or patient-specific advice. Keep practice within your role and follow local policies.</p>`;};
PX_ACTIONS['px-filter']=([k,v])=>{if(!['level','skill'].includes(k))return;ui.practice[k]=v;render();};
const pxOrigHandleChange=handleChange;
handleChange=function(event){const el=event.target;if(el.dataset&&el.dataset.field==='px-group'){ui.practice.group=el.value==='skill'?'skill':'level';render();return;}return pxOrigHandleChange.apply(this,arguments);};

/* ---------- 13. My Growth, logging, bootstrap ---------- */
const pxOrigRenderGrowth=renderGrowth;
renderGrowth=function(){const html=pxOrigRenderGrowth(),cov=pxCoverage(),tried=HCA_ACTIVITIES.filter(a=>pxDone(a.id)).length;const sec=`<section class="px-growth"><div class="section-title"><h2>Practice skills</h2>${btn('Go to Practice','navigate',['practice'],'secondary')}</div><div class="px-radarwrap">${pxRadar(cov)}<ul class="px-skilllist">${cov.map(c=>`<li><span>${pxSkillChip(c.skill.id)}</span><span class="px-sk-n">${c.done} of ${c.total}</span><span class="px-sk-l">${c.reached?pxLevel(['','foundation','core','advanced'][c.reached]).name+' reached':'Not started'}</span></li>`).join('')}</ul></div><p class="field-hint">${tried} activities tried. Coverage shows what you have rehearsed, not competence.</p></section>`;return html.replace('<section class="growth-grid">',sec+'<section class="growth-grid">');};
const pxOrigBootstrap=bootstrap;
bootstrap=function(){Object.assign(actions,PX_ACTIONS);return pxOrigBootstrap.apply(this,arguments);};

/* ---------- 14. Legacy studios and simulations: confidence ratings, decision-path map, sequence map ---------- */
function pxCommit(fn){captureActivity();(ui.history||(ui.history=[])).push(structuredClone(state.lastSession));ui.history=ui.history.slice(-50);ui.dirty=!!ui.activity;fn();}
function pxDecisionItems(s,a){return a.history.map((h,i)=>{const sc=s.scenes[i];return {title:sc[0],q:h.correct?'best':'risk',you:h.choice,better:sc[3][sc[4]],betterWhy:sc[5][sc[4]],cons:h.feedback,why:h.feedback,conf:(a.pxConf||[])[i]||0};});}
const pxOrigRenderStudio=ccRenderStudio;
ccRenderStudio=function(){pxOrigRenderStudio();if(!ccStudio)return;const s=CC_STUDIOS.find(x=>x.id===ccStudio.id),a=ccStudio,body=document.getElementById('modalBody');if(!s||!body)return;
 if(s.mode==='sequence'&&a.checked&&a.order.length===s.steps.length){const rep=body.querySelector('.cc-studio-report');if(rep&&!body.querySelector('.px-seqfig'))rep.insertAdjacentHTML('beforeend',pxSeqCompare(s.steps,a.order,{caption:'Your sequence against the intended sequence'}));return;}
 if(s.mode!=='decisions')return;
 if(a.index>=s.scenes.length){const rows=(a.pxConf||[]).map((c,i)=>({conf:c,q:a.history[i]?.correct?'best':'risk'})).filter(r=>r.conf),head=body.querySelector('.cc-studio-head');if(head&&!body.querySelector('.px-pathmap')){const calib=pxCalibStats(rows);head.insertAdjacentHTML('afterend',`<section class="px-sec"><h3>Your decision path</h3>${pxPathMap(pxDecisionItems(s,a))}</section>${rows.length?`<section class="px-sec"><h3>Confidence and calibration</h3>${pxCalibMatrix(rows)}<p>${esc(pxCalibText(calib))}</p></section>`:''}`);}return;}
 const q=s.scenes[a.index],answers=[...body.querySelectorAll('button.answer')];if(a.selected===null){answers.forEach((b,i)=>{b.removeAttribute('data-engine-37');b.setAttribute('data-action','px-cpick');b.setAttribute('data-arg0',String(i));b.setAttribute('aria-pressed',String(a.pxSel===i));if(a.pxSel===i)b.classList.add('is-selected');});
  if(a.pxSel!==null&&a.pxSel!==undefined){const last=answers.at(-1);last.insertAdjacentHTML('afterend',`<div class="px-rate" role="radiogroup" aria-label="How sure are you that this is the strongest response?"><span class="px-pref-l">How sure are you that this is the strongest response?</span><div class="px-seg">${[[1,'Not sure'],[2,'Fairly sure'],[3,'Very sure']].map(([v,t])=>`<button type="button" class="px-segbtn" role="radio" aria-checked="${a.pxRate===v}" data-action="px-crate" data-arg0="${v}">${t}</button>`).join('')}</div><div class="modal-actions"><button type="button" class="btn" ${a.pxRate?'':'disabled'} data-action="px-clock">Lock in my answer →</button></div></div>`);}}
 else{const c=(a.pxConf||[])[a.index],good=a.selected===q[4],fb=body.querySelector('.feedback');if(c&&fb){const msg=c===3&&!good?'You were very sure here, and this was not the strongest option. Worth noticing.':c===1&&good?'You were unsure, yet chose the strongest option. Your instinct served you.':c===3?'Very sure and strong. Well calibrated.':'';if(msg&&!fb.querySelector('.px-calib-note'))fb.insertAdjacentHTML('beforeend',`<p class="px-calib-note">${esc(msg)}</p>`);}}};
PX_ACTIONS['px-cpick']=([i])=>{if(!ccStudio||ccStudio.selected!==null)return;ccStudio.pxSel=+i;ccStudio.pxRate=0;ccRenderStudio();};
PX_ACTIONS['px-crate']=([n])=>{if(!ccStudio||ccStudio.pxSel===null||ccStudio.pxSel===undefined)return;ccStudio.pxRate=+n;ccRenderStudio();};
PX_ACTIONS['px-clock']=()=>{if(!ccStudio||ccStudio.pxSel===null||ccStudio.pxSel===undefined||!ccStudio.pxRate)return;pxCommit(()=>{const i=ccStudio.pxSel,r=ccStudio.pxRate;(ccStudio.pxConf=ccStudio.pxConf||[])[ccStudio.index]=r;ccStudio.pxSel=null;ccStudio.pxRate=0;ccDecisionAnswer(i);});};
const pxOrigRenderSim=ccRenderSimulation;
ccRenderSimulation=function(){pxOrigRenderSim();if(!ccSim||!ccSim.finished)return;const s=CC_SIMS.find(x=>x.id===ccSim.id),body=document.getElementById('modalBody'),head=body&&body.querySelector('.cc-studio-head');if(!head||body.querySelector('.px-pathmap'))return;
 const items=s.zones.map((z,i)=>{const pick=ccSim.answers[i],best=pick===z.correct;return {title:z.name,fw:z.label,q:best?'best':'risk',you:z.answers[pick],better:z.answers[z.correct],betterWhy:z.why[z.correct],cons:z.why[pick],why:z.why[pick]};});head.insertAdjacentHTML('afterend',`<section class="px-sec"><h3>Your decision path</h3>${pxPathMap(items)}</section>`);};

