  steps:[{b:'S',t:'Situation',f:[0]},{b:'B',t:'Background',f:[1]},{b:'A',t:'Assessment',f:[2]},{b:'R',t:'Recommendation',f:[3]},{b:'↺',t:'Close the loop',f:[4]}],shape:'chain',
